const CONTENT15 = {"talents":{"md":{"bone":[{"name":"Xương Cốt Bê Tông","tag":"Chịu đòn tốt, sức bền cao.","story":"Bạn lớn lên ở Chung cư Ánh Dương, từng bị một mảng trần sập đè suốt buổi chiều mà vẫn bò ra được, lưng đầy bụi vôi."},{"name":"Da Dày Qua Dịch","tag":"Thể chất cứng cáp, khó gục.","story":"Bạn là đứa trẻ duy nhất ở khu cách ly Hồng Phúc chịu nổi ba cơn sốt Hoại Huyết; từ đó, những cú đánh chỉ khiến bạn chao người."},{"name":"Con Nhà Bốc Vác","tag":"Máu nhiều, sức chịu đựng cao.","story":"Bạn từng theo mẹ khuân bao gạo lên mười tầng cầu thang mất điện; vai bầm tím, còn chân thì chưa lần nào chịu khuỵu."}],"swift":[{"name":"Chân Qua Khe Cửa","tag":"Chạy nhanh, né đòn giỏi.","story":"Bạn học chạy trong những hành lang chung cư đầy xác sống, nơi chậm một nhịp là cánh cửa sắt đóng ngay trước mũi."},{"name":"Bóng Lướt Đường Ray","tag":"Di chuyển lanh lẹ.","story":"Bạn từng nhặt đồ rơi giữa hai đường ray Ga ngầm Bến Cũ, nghe tiếng tàu bảo trì là đã bật lên sân ga trước khi đèn pha quét tới."},{"name":"Đứa Trẻ Mái Tôn","tag":"Thoát hiểm bằng tốc độ.","story":"Bạn lớn lên trên những mái tôn chợ đêm, quen nhảy qua khe nhà mỗi khi đám tuần tra kéo đến; đôi giày nào cũng mòn ở mũi."}],"eye":[{"name":"Mắt Qua Kính Vỡ","tag":"Dễ ngắm trúng điểm yếu.","story":"Bạn từng ngồi hàng giờ bên cửa kính vỡ, chỉ cho cha vết nứt nhỏ trên giáp của lũ xác sống; phát bắn của ông hiếm khi trượt."},{"name":"Con Ngươi Đèn Đỏ","tag":"Nhãn lực sắc, thiện xạ.","story":"Bạn sinh dưới ánh đèn cấp cứu Hồng Phúc và lớn lên bằng trò đếm kim tiêm trong khay tối; những thứ bé xíu chẳng mấy khi lọt khỏi mắt bạn."},{"name":"Ngắm Qua Màn Mưa","tag":"Nhìn rõ mục tiêu hiểm yếu.","story":"Bạn học bắn lon trên sân thượng Chung cư Ánh Dương giữa những trận mưa bụi; sau này, một khe hở trên mũ bảo hộ cũng đủ để bạn nhắm."}],"might":[{"name":"Nắm Đấm Phá Khóa","tag":"Đòn cận chiến nặng tay.","story":"Bạn mới mười tuổi đã đấm bung ổ khóa kho gạo khi em gái bị nhốt bên trong; ông thợ khóa nhìn cánh cửa méo mà bỏ luôn lời mắng."},{"name":"Vai Gánh Cửa Sắt","tag":"Sức mạnh bẩm sinh vượt trội.","story":"Bạn sinh ra đã to hơn đám trẻ cùng khu; ngày Ga ngầm Bến Cũ ngập nước, chính vai bạn giữ cửa chống lũ đủ lâu cho mọi người chạy."},{"name":"Máu Nhà Đập Đá","tag":"Cận chiến đầy uy lực.","story":"Bạn từng phụ bà ngoại đập gạch lấy đường thoát khỏi tòa nhà cháy; cái búa quá nặng với trẻ con, nhưng vào tay bạn lại nhẹ tênh."}],"sage":[{"name":"Não Nhớ Một Lần","tag":"Học nhanh, tiến bộ nhanh.","story":"Bạn xem y tá Hồng Phúc băng vết thương một lần rồi làm lại đúng từng nút thắt trên con gấu bông rách bụng."},{"name":"Đọc Giữa Tiếng Còi","tag":"Dễ lĩnh hội kỹ năng mới.","story":"Bạn học chữ từ những bảng hướng dẫn sơ tán ở ga ngầm; giữa tiếng còi báo động, bạn vẫn hiểu cách vận hành máy lọc nước trước cả người lớn."},{"name":"Đầu Óc Nhặt Mảnh","tag":"Rút kinh nghiệm rất nhanh.","story":"Bạn nhặt sách kỹ thuật rách ở Chợ đêm Phố Đèn, ghép trang bằng băng dính; hôm sau đã chỉ cho thợ cách sửa chiếc máy phát điện cũ."}],"mana":[{"name":"Giếng Sáng Trong Ngực","tag":"Nguồn năng lượng dồi dào.","story":"Bạn sốt li bì bên một lõi linh khí nứt vỡ hồi nhỏ; khi tỉnh dậy, bóng đèn đầu giường cứ sáng mỗi lần bạn thở mạnh."},{"name":"Mạch Đập Lam","tag":"Trữ được nhiều linh khí.","story":"Bạn sinh ở trạm điện bỏ hoang đúng đêm cơn bão Hoại Huyết quét qua; từ bé, lòng bàn tay bạn đã làm kim đo năng lượng rung mãi không thôi."},{"name":"Bình Chứa Trời Mưa","tag":"Năng lượng bền và đầy.","story":"Bạn từng trú mưa dưới mái trạm phát sóng suốt ba ngày, ôm chặt viên tinh thạch nhặt được; từ đó, dùng hết sức rồi bạn vẫn còn dư một chút."}],"fortune":[{"name":"Tay Nhặt Đúng Túi","tag":"Hay tìm được đồ tốt.","story":"Bạn từng lục chiếc balô cuối cùng trong bãi xe bỏ hoang và thấy thuốc cho mẹ, dù mười chiếc trước chỉ toàn giấy ướt."},{"name":"Đồng Xu Mặt Ngửa","tag":"Vận may theo chân.","story":"Bạn nhặt một đồng xu dưới cầu thang chợ đêm; mỗi lần nó lăn khỏi tay, bạn lại tìm thấy một ngăn tủ người khác chưa kịp mở."},{"name":"Hên Từ Đống Rác","tag":"Dễ gặp vật phẩm quý.","story":"Bạn lớn lên bằng việc bới rác sau Hồng Phúc; đúng hôm cả khu thiếu pin, bạn moi ra một hộp pin còn nguyên giữa đống bông băng mốc."}],"regen":[{"name":"Sẹo Chưa Kịp Lên","tag":"Vết thương lành nhanh.","story":"Bạn bị kính cứa sâu khi trèo khỏi xe buýt lúc nhỏ; sáng hôm sau, bác sĩ bóc băng chỉ thấy một vệt hồng mỏng."},{"name":"Máu Biết Quay Về","tag":"Hồi phục nhanh bất thường.","story":"Bạn ngã vào hàng rào thép gai sau trường học; trước khi mẹ tìm được thuốc sát trùng, máu đã ngừng chảy và da bắt đầu khép lại."},{"name":"Da Non Qua Đêm","tag":"Tự chữa lành rất nhanh.","story":"Bạn từng bị xác sống cào rách bắp tay ở sân chung cư; cả nhà thức trắng canh sốt, còn bạn sáng ra chỉ than áo dính vào da non."}],"shadow":[{"name":"Đứa Trẻ Nhà Xác","tag":"Dễ gọi hồn và thu phục bóng.","story":"Bạn lớn lên sau nhà xác Hồng Phúc, nơi những cái bóng thường ngồi im nghe bạn kể chuyện trước giờ ngủ."},{"name":"Tiếng Gõ Dưới Ga","tag":"Xác sống dễ nghe lời.","story":"Bạn từng lạc một đêm trong đường hầm Ga ngầm Bến Cũ; thay vì cắn, một xác sống già gõ ba tiếng lên tường rồi dẫn bạn ra lối thoát."},{"name":"Sinh Giữa Khăn Tang","tag":"Có duyên với cõi chết.","story":"Bạn sinh đúng buổi khu trú ẩn làm lễ tiễn người chết; từ bé, cứ đứng bên đèn cúng là bạn nghe những tiếng gọi mà người khác không nghe."}],"ward":[{"name":"Mệnh Qua Cửa Hẹp","tag":"Hiểm nghèo vẫn sống.","story":"Bạn lọt khỏi chiếc xe cứu thương lật nghiêng chỉ vài giây trước khi nó bốc cháy; người ta bảo bạn có hai mạng, mẹ bạn bảo đừng thử lại."},{"name":"Kẻ Sót Danh Sách","tag":"Khó chết trong tai ương.","story":"Bạn bị ghi tên vào danh sách tử vong sau vụ sập hầm Bến Cũ; ba ngày sau, bạn tự mò về, tay còn ôm chiếc đèn pin hết điện."},{"name":"Thở Dưới Đống Gạch","tag":"Sống sót rất dai.","story":"Bạn từng nằm dưới quầy thuốc đổ nát suốt một đêm, thở qua khe gạch hẹp bằng ngón tay; sáng ra còn đủ sức gọi cứu hộ."}],"trade":[{"name":"Miệng Đổi Ra Gạo","tag":"Buôn bán khéo, dễ kiếm tiền.","story":"Bạn bán ba viên bi cũ lấy hai ổ bánh ở Chợ đêm Phố Đèn; người mua còn vui vẻ hẹn mai quay lại."},{"name":"Ngón Tay Cân Giá","tag":"Nhìn hàng, chốt giá giỏi.","story":"Bạn ngồi dưới sạp mẹ từ lúc biết đi, nghe tiếng hộp lắc đã đoán được số pin còn tốt và chẳng bao giờ chịu trả quá giá."},{"name":"Con Buôn Cầu Thang","tag":"Tiền bạc đến dễ hơn.","story":"Bạn từng đổi một cuộn dây đồng lấy thuốc ho cho cả tầng chung cư, rồi bán phần dây thừa đủ tiền mua bữa tối."}],"craft":[{"name":"Tay Vá Ngày Tàn","tag":"Chế tạo và sửa chữa hiệu quả.","story":"Bạn lớn lên bên bàn sửa đồ của bố, từng biến quạt hỏng thành máy thổi bếp giữa mùa mưa lạnh."},{"name":"Dao Gọn Một Nhát","tag":"Khai thác vật liệu khéo.","story":"Bạn học đốn củi ở bãi đất sau khu trú ẩn; rìu của bạn luôn bổ trúng thớ gỗ, để lại ít mảnh vụn hơn người lớn."},{"name":"Mũi Chỉ Cứu Người","tag":"Làm thuốc, dụng cụ chắc tay.","story":"Bạn từng phụ cô y tá khâu túi cứu thương bằng chỉ tháo từ áo cũ; nhờ đường may kín của bạn, lọ thuốc cuối cùng sống qua trận mưa."}],"lead":[{"name":"Người Giữ Hàng Đèn","tag":"Đồng đội dễ tin theo.","story":"Bạn từng xếp đám trẻ lạc thành một hàng, bắt mỗi đứa cầm vạt áo đứa trước để đi qua đường hầm tối; chẳng ai bị bỏ lại."},{"name":"Giọng Nói Sau Còi","tag":"Dễ tập hợp và kết thân.","story":"Bạn mới mười hai tuổi đã đứng trên thùng hàng gọi mọi người chia nước khi còi sơ tán im bặt; cả khu nghe lời vì bạn chia phần mình trước."},{"name":"Vai Dựa Mùa Dịch","tag":"Dẫn dắt bằng sự tin cậy.","story":"Bạn canh cho hàng xóm ngủ từng lượt trong tuần mất điện đầu tiên; từ đó, hễ phải chọn người dẫn đường, họ lại nhìn về phía bạn."}],"slayer":[{"name":"Mắt Chọn Con Đầu Đàn","tag":"Đặc biệt giỏi săn kẻ mạnh.","story":"Bạn từng thấy con xác sống chỉ huy cả bầy bằng một tiếng rít; lúc mọi người chạy, bạn nhớ đúng nơi nó khập khiễng ở chân trái."},{"name":"Kẻ Đếm Nhịp Quái","tag":"Dễ tìm sơ hở của trùm.","story":"Bạn lớn lên xem Đội Cứu Hộ Bình Minh tập đánh con đột biến; bạn nhận ra nó luôn ngừng thở một nhịp trước khi vung tay."},{"name":"Nanh Nhắm Nanh","tag":"Đối đầu tinh anh hiệu quả.","story":"Bạn từng cứu anh trai khỏi một con xác sống giáp dày bằng cách chọc vào khớp cổ tay nó; từ đó, thứ càng đáng sợ càng khiến bạn nhìn kỹ."}],"fury":[{"name":"Máu Nóng Qua Vết Rách","tag":"Bị thương càng đánh dữ.","story":"Bạn bị cào rách trán trong lần đầu giữ cửa khu trú ẩn; càng đau, bạn càng đánh mạnh, đến lúc buông gậy thì vết cào đã se lại."},{"name":"Cơn Đói Đỏ","tag":"Đánh trả để hút lại sinh lực.","story":"Bạn từng đổ máu trên sàn phòng tập Hồng Phúc, rồi thấy hơi sức quay về mỗi lần nắm đấm trúng bao cát bọc da nhiễm bệnh."},{"name":"Đòn Cuối Chưa Hết","tag":"Càng nguy cấp càng hung hãn.","story":"Bạn bị dồn vào góc bếp khi còn nhỏ, tay rớm máu vì mảnh chai; cú phản đòn sau đó mạnh đến mức cả nhà phải kéo bạn ra."}],"mind":[{"name":"Hơi Thở Giữa Còi","tag":"Bình tâm để hồi năng lượng.","story":"Bạn học đếm hơi thở cạnh mẹ trong hầm trú bom; giữa tiếng còi xé tai, năng lượng trong người bạn lại đầy dần."},{"name":"Mặt Hồ Trong Ga","tag":"Giữ tĩnh lặng, hồi sức nhanh.","story":"Bạn từng ngồi nhìn vũng nước phản chiếu đèn ga suốt đêm bị kẹt dưới hầm; càng thôi sợ, bạn càng thấy sức lực trở lại."},{"name":"Im Lặng Có Lửa","tag":"Tâm tĩnh giúp hồi năng lượng.","story":"Bạn học ngồi yên bên ông ngoại đang hấp hối, nghe tiếng máy trợ thở thay cho đồng hồ; chính những phút lặng đó nuôi lại nguồn lực trong bạn."}],"frail":[{"name":"Xương Mỏng Như Kính","tag":"Ít máu, dễ bị thương.","story":"Bạn từng gãy cổ tay chỉ vì trượt khỏi bậc thềm Hồng Phúc; từ đó, một cú va trong lúc chạy loạn cũng đủ khiến bạn phải nghỉ cả ngày."},{"name":"Đứa Trẻ Lồng Kính","tag":"Thể chất yếu ớt.","story":"Bạn lớn lên trong phòng cách ly, nhìn đám trẻ đá bóng qua ô cửa; ra ngoài rồi, một cơn sốt nhẹ vẫn có thể quật bạn nằm bẹp."},{"name":"Da Giấy Mùa Dịch","tag":"Chịu đòn rất kém.","story":"Bạn sinh thiếu tháng giữa đợt thiếu thuốc, da mỏng đến mức băng dính cũng làm rách; lớn lên, mỗi vết thương đều lấy của bạn nhiều sức hơn người khác."}],"slow":[{"name":"Chân Chờ Thang Máy","tag":"Di chuyển chậm chạp.","story":"Bạn từng mắc kẹt nhiều tháng trong căn hộ chật vì hành lang đầy xác sống; ngày được ra ngoài, chân bạn chạy vài bước đã nặng như đeo đá."},{"name":"Bước Sau Tiếng Còi","tag":"Khó tăng tốc khi nguy hiểm.","story":"Bạn bị kẹt bàn chân dưới cửa cuốn chợ đêm hồi nhỏ; nó lành rồi, nhưng mỗi lần nghe còi báo động, chân bạn vẫn chậm mất một nhịp."},{"name":"Gót Giày Dính Bùn","tag":"Bước chân ì ạch.","story":"Bạn lớn lên ở khu ngập nước, ngày nào cũng lội bùn kéo xe hàng; lên đường khô rồi, bạn vẫn bước nặng nề và thường về cuối hàng."}],"glutton":[{"name":"Bụng Không Đáy","tag":"Đói nhanh, tốn lương thực.","story":"Bạn từng ăn hết khẩu phần ba ngày ngay sau cơn sốt Hoại Huyết đầu đời; giờ mỗi chuyến đi, túi đồ phải chừa thêm chỗ cho thức ăn của bạn."},{"name":"Cổ Họng Khô Rát","tag":"Khát thường xuyên.","story":"Bạn lớn lên cạnh bể nước nhiễm bẩn, phải nhấp từng nắp chai; từ đó, cổ họng cứ khô ran và bình nước của cả đội vơi nhanh hơn."},{"name":"Miệng Nhai Lúc Canh","tag":"Cần ăn nhiều mới đủ sức.","story":"Bạn từng ăn vụng mì khô ngay trong ca gác vì bụng réo át tiếng bước chân; may chưa có xác sống tới, nhưng đồng đội mất luôn bữa sáng."}],"unlucky":[{"name":"Túi Toàn Nắp Chai","tag":"Khó nhặt được đồ tốt.","story":"Bạn mở chiếc hòm cứu trợ đầu tiên trong đời và chỉ thấy nắp chai gỉ; đến giờ, ngăn tủ bạn chọn thường vẫn là ngăn trống."},{"name":"Số Trúng Hàng Hỏng","tag":"Vật phẩm rơi ra thường kém.","story":"Bạn từng bốc đúng viên pin chảy nước giữa cả hộp pin mới ở chợ đêm; người ta cười, còn bạn phải đi bộ về trong tối."},{"name":"Vận May Đi Lạc","tag":"Hiếm gặp chiến lợi phẩm tốt.","story":"Bạn nhặt được túi cứu thương sau vụ sập ga, nhưng bên trong toàn băng gạc mốc; từ đó, bạn luôn là người mở ra món đồ tệ nhất."}],"clumsy":[{"name":"Ngón Tay Kẹt Đạn","tag":"Nạp chậm, bắn thiếu chính xác.","story":"Bạn từng làm rơi cả băng đạn xuống cống trong buổi tập đầu tiên; đến giờ, cứ cần nạp gấp là tay lại vướng, phát bắn dễ đi chệch."},{"name":"Mắt Nhắm Sai Bên","tag":"Dùng vũ khí tầm xa vụng về.","story":"Bạn học ngắm bắn qua khe tường quá hẹp, quen nhắm một mắt rồi nheo nhầm mắt còn lại; cái giá là đạn tốn hơn mục tiêu."},{"name":"Dây Ná Rối Tay","tag":"Khó ngắm và thay đạn nhanh.","story":"Bạn từng buộc dây ná vào chính cổ tay mình khi định bắn đuổi chuột; lớn lên cầm súng, bạn vẫn luống cuống với khóa và hộp đạn."}],"weak":[{"name":"Nắm Đấm Bông Gòn","tag":"Đòn cận chiến yếu.","story":"Bạn từng đánh hết sức vào cửa phòng bị kẹt mà chỉ làm bong sơn; từ đó, mỗi lần giáp lá cà, bạn phải đánh thêm vài cú mới mong thoát."},{"name":"Tay Không Giữ Nổi Gậy","tag":"Sức đánh gần kém.","story":"Bạn sinh ra với đôi cổ tay yếu, hồi nhỏ xách can nước nửa đường đã buông; giờ vung gậy mạnh một chút là tay run, đòn cũng nhẹ đi."},{"name":"Cú Đấm Xin Lỗi","tag":"Cận chiến thiếu uy lực.","story":"Bạn từng tập tự vệ với chị ở Ga ngầm Bến Cũ; chị bảo cú đấm của bạn giống gõ cửa, và xác sống thì chẳng bao giờ lịch sự mở cho."}],"dull":[{"name":"Học Qua Ba Lần Đau","tag":"Tiếp thu kinh nghiệm chậm.","story":"Bạn từng chạm vào hàng rào điện hai lần dù biển cảnh báo treo ngay trước mặt; bài học nào cũng phải trả bằng vài vết bỏng mới nhớ."},{"name":"Đầu Chậm Một Trang","tag":"Lên tay chậm hơn người khác.","story":"Bạn mất cả mùa mưa để học cách thay lõi máy lọc mà em gái chỉ xem một lần đã biết; mọi kỹ năng mới đều ngốn của bạn thêm thời gian."},{"name":"Nhớ Sau Tiếng Mắng","tag":"Ít rút được kinh nghiệm.","story":"Bạn từng lạc cùng một ngã rẽ trong ga ngầm suốt ba buổi; đồng đội phải quay lại tìm, còn bạn mất thêm nhiều chuyến mới thuộc đường."}],"dark":[{"name":"Sợ Khi Đèn Tắt","tag":"Ban đêm chiến đấu kém.","story":"Bạn từng bị nhốt nhầm trong kho lạnh Hồng Phúc khi mất điện; giờ trời vừa tối là tay cầm vũ khí đã run, dù trước mặt chưa có gì."},{"name":"Bóng Đè Cuối Hành Lang","tag":"Trong tối dễ mất bình tĩnh.","story":"Bạn thấy xác sống đầu tiên bước ra từ cuối hành lang không đèn hồi sáu tuổi; mỗi trận đánh ban đêm, bạn lại nhìn nhầm bóng và ra đòn chậm."},{"name":"Mắt Chờ Bình Minh","tag":"Sức chiến đấu giảm về đêm.","story":"Bạn từng thức trắng trên mái nhà nghe tiếng móng cào dưới cửa; từ đó, thiếu ánh mặt trời là bạn mất tập trung và tốn đạn hơn."}],"poor":[{"name":"Ví Rỗng Từ Bé","tag":"Kiếm được ít tiền hơn.","story":"Bạn từng đổi cả túi đồ nhặt được lấy một ổ bánh cứng vì không biết mặc cả; ở chợ đêm, tiền vào tay bạn vẫn mỏng như thế."},{"name":"Phần Lời Để Lại","tag":"Khó giữ phần tiền mình kiếm.","story":"Bạn học bán hàng ở sạp thuốc của mẹ, nhưng hễ thấy người mua ho nặng là tự bớt giá; cái bụng họ ấm lên, còn ví bạn thì không."},{"name":"Đồng Tiền Mẻ Cạnh","tag":"Thu nhập ít ỏi.","story":"Bạn từng được trả bằng xu mẻ sau cả ngày dọn kho, vẫn không dám đòi thêm; lớn lên, người ta thường ép giá công của bạn."}],"leak":[{"name":"Mạch Tắc Dưới Da","tag":"Trữ được ít năng lượng.","story":"Bạn sốt cao sau lần chạm vào lõi linh khí vỡ ở trường; từ đó, năng lượng trong người cứ nghẹn lại, dùng vài lần đã cạn."},{"name":"Bình Rạn Không Tiếng","tag":"Mana ít, mau hết.","story":"Bạn từng được thầy ở khu trú ẩn đo mạch linh khí; kim vừa nhích đã tụt, như chiếc bình mẹ vá mãi vẫn rò nước."},{"name":"Hơi Sáng Đứt Quãng","tag":"Khó duy trì nguồn linh khí.","story":"Bạn sinh đúng đêm trạm phát năng lượng tắt phụt; từ bé, ánh sáng gọi lên từ tay bạn chỉ le lói một lúc rồi tắt, buộc bạn phải dùng dè sẻn."}],"feud":[{"name":"Món Nợ Bằng Máu","tag":"Có kẻ luôn truy sát.","story":"Bạn từng làm đổ chuyến thuốc lậu của một tay buôn chợ đêm để cứu bạn mình; hắn mất cả gia tài và đến giờ vẫn nhớ mặt bạn."},{"name":"Tên Trên Tường Truy Nã","tag":"Bị một phe săn đuổi.","story":"Bạn nhặt được sổ ghi tên người mất tích hồi nhỏ và lỡ đưa nó cho Hội Người Gác Đèn; kẻ viết sổ treo thưởng tìm bạn, khiến đường về nhà chẳng còn yên."},{"name":"Thù Từ Cánh Cửa","tag":"Kẻ thù bám theo dai dẳng.","story":"Bạn đóng cửa hầm để chặn bầy xác sống, bỏ lại thủ lĩnh một băng cướp ở phía ngoài; hắn sống sót và thề sẽ bắt bạn trả giá."}],"lone":[{"name":"Ghế Trống Bên Cạnh","tag":"Khó kết thân với người khác.","story":"Bạn lớn lên trong phòng cách ly, quen ăn một mình qua ô kính; ra khỏi đó, bạn vẫn né lời mời ngồi chung và thường phải tự xoay xở."},{"name":"Người Không Gọi Tên","tag":"Đồng đội dễ dè chừng.","story":"Bạn từng im lặng suốt ba ngày sau khi người thân biến đổi; người trong khu nghe đồn bạn biết trước chuyện đó, và từ ấy chẳng ai dám đứng quá gần."},{"name":"Bóng Đi Sau Đoàn","tag":"Khó gây dựng sự tin cậy.","story":"Bạn lạc đoàn sơ tán hồi nhỏ rồi tự sống qua mùa đông; thói quen giấu đồ trong áo giúp bạn sống sót, nhưng khiến bạn mới quen khó tin tưởng."}]},"tt":{"bone":[{"name":"Thiết Cốt Đồng Sinh","tag":"Xương cứng, chịu đòn bền bỉ.","story":"Bạn sinh dưới chân Thanh Vân Sơn, ba tuổi đã bị đá lở vùi suốt một đêm. Khi được đào lên, bạn chỉ trầy da, còn tảng đá đè trên lưng đã nứt đôi."},{"name":"Huyết Ngưu Chi Thể","tag":"Khí huyết dồi dào, khó quật ngã.","story":"Bạn từng uống nhầm bát huyết dược của Dược Vương Cốc lúc còn thơ. Từ đó, mỗi lần ngã lăn trên nền đá, bạn lại đứng dậy trước khi người lớn kịp đỡ."},{"name":"Cốt Tùng Qua Đông","tag":"Thân thể dẻo dai trước thương tích.","story":"Bạn lớn lên bên vực tuyết, mùa đông phải vác củi qua đường núi đóng băng. Năm tám tuổi, bạn rơi xuống khe sâu mà chỉ ôm bó củi trở về, xương cốt vẫn nguyên vẹn."}],"swift":[{"name":"Phong Ảnh Bộ","tag":"Chạy nhanh, né đòn linh hoạt.","story":"Bạn từng bị bầy lang ở Vạn Thú Sơn Mạch đuổi suốt một buổi chiều. Từ đó, đôi chân bạn quen lách qua rễ cây và phiến đá nhanh như gió lọt qua rừng."},{"name":"Lạc Hà Truy Phong","tag":"Thân pháp nhẹ như gió chiều.","story":"Bạn lớn lên ở Trấn Lạc Hà, ngày nào cũng chạy theo con diều mắc trên mái ngói. Đến năm lên chín, bạn đã nhảy qua ba nóc nhà trước khi diều chạm đất."},{"name":"Yến Lướt Mặt Hồ","tag":"Dễ thoát thân, tránh đòn mau lẹ.","story":"Bạn bị sư huynh ném xuống Hồ Tẩy Kiếm để học bơi khi còn nhỏ. Trong lúc hoảng loạn, bạn đạp qua những phiến lá sen, thân hình thoắt hiện thoắt mất."}],"eye":[{"name":"Phá Vân Linh Mục","tag":"Nhìn rõ kẽ hở, ra đòn hiểm.","story":"Bạn từng nhặt mũi kim cho mẹ giữa sân đầy cát lúc mới năm tuổi. Từ hôm ấy, ngay cả vết nứt mảnh trên vảy yêu thú cũng khó lọt khỏi mắt bạn."},{"name":"Ưng Đồng Điểm Huyệt","tag":"Ngắm chuẩn điểm yếu từ xa.","story":"Bạn theo thợ săn lên núi, thấy con ưng non rơi khỏi tổ và chăm nó suốt một mùa mưa. Những ngày cùng nó dõi tìm chuột giữa đồng cỏ đã rèn đôi mắt bạn sắc lạ thường."},{"name":"Tẩy Kiếm Minh Nhãn","tag":"Tinh mắt, dễ đánh trúng yếu huyệt.","story":"Thuở bé, bạn nhìn bóng kiếm phản chiếu dưới Hồ Tẩy Kiếm mỗi bình minh. Một hôm, bạn chỉ đúng vết mẻ nhỏ trên lưỡi kiếm chìm sâu dưới nước, khiến lão kiếm tu kinh ngạc."}],"might":[{"name":"Kình Sơn Thần Lực","tag":"Đòn cận chiến nặng như núi.","story":"Bạn sinh trong nhà đốn đá, bảy tuổi đã nhấc chiếc cối xay mà ba người lớn không xoay nổi. Từ đó, nắm đấm nhỏ của bạn làm cọc gỗ trước sân lung lay."},{"name":"Hổ Tí Thiên Thành","tag":"Sức tay bẩm sinh vượt thường nhân.","story":"Bạn từng kéo một con nghé sa lầy khỏi ruộng sau trận mưa lớn. Bùn ngập đến ngực, vậy mà bạn còn ôm nó chạy về chuồng trước khi trời tối."},{"name":"Bá Quyền Mộc Tử","tag":"Cận chiến uy mãnh, lực đạo lớn.","story":"Lúc nhỏ, bạn luyện quyền bằng cách giã hạt dẻ trong cối đá cho bà. Năm lên mười, một quyền lỡ tay của bạn đã đập thủng cả đáy cối."}],"sage":[{"name":"Nhất Văn Thập Ngộ","tag":"Lĩnh hội nhanh, tu luyện chóng tiến.","story":"Bạn nghe đạo trưởng giảng kinh ngoài cổng Thanh Vân Tông một lần khi còn chăn trâu. Tối ấy, bạn dùng cành khô vẽ lại trọn bộ trận đồ trên nền đất."},{"name":"Minh Tâm Đồng Tử","tag":"Học một hiểu nhiều, dễ đột phá.","story":"Bạn nhặt được nửa trang kiếm quyết bị mưa làm nhòe bên Hồ Tẩy Kiếm. Chỉ từ vài nét mực còn sót, bạn tự luyện ra thức kiếm khiến vị sư tỷ đi ngang phải dừng chân."},{"name":"Ngộ Đạo Dưới Đèn","tag":"Tiếp thu nhanh mọi pháp môn.","story":"Bạn từng thức trắng đêm xem cha sửa một lò luyện đan nứt vách. Sáng ra, bạn chỉ đúng chỗ khí nóng thất thoát và tự tay bịt kín nó bằng đất sét."}],"mana":[{"name":"Linh Hải Vô Nhai","tag":"Linh khí dồi dào, dùng thuật bền lâu.","story":"Bạn lọt lòng giữa cơn mưa linh khí trên Thanh Vân Sơn. Thuở bé, mỗi khi bạn ngủ dưới mái hiên, giọt mưa đọng quanh nôi lại sáng lên như vụn sao."},{"name":"Cửu Tuyền Khí Mạch","tag":"Đan điền chứa nhiều linh lực.","story":"Bạn từng ngã xuống giếng cổ ở Dược Vương Cốc và được vớt lên cùng một dòng nước xanh. Từ đó, mỗi lần vận khí, trong đan điền bạn lại vang tiếng suối chảy."},{"name":"Tinh Hà Tụ Khí","tag":"Hút nạp linh khí hơn người.","story":"Năm bảy tuổi, bạn ngủ quên trên đài quan tinh bỏ hoang. Khi tỉnh dậy, hơi thở bạn kéo từng sợi linh quang từ kẽ đá về quanh mình."}],"fortune":[{"name":"Phúc Tinh Lạc Túi","tag":"Thường gặp may, dễ nhặt bảo vật.","story":"Bạn mua một chiếc túi rách ở chợ Trấn Lạc Hà để đựng bánh. Về nhà, bạn phát hiện dưới lớp vải lót có một viên linh thạch thượng phẩm."},{"name":"Hữu Duyên Kỳ Bảo","tag":"Cơ duyên tốt thường tự tìm đến.","story":"Bạn đuổi theo con bướm trắng vào hang núi khi còn nhỏ. Con bướm bay mất, nhưng dưới chỗ bạn đặt chân lại lộ ra hộp ngọc chôn từ nhiều năm trước."},{"name":"Kim Diệp Theo Chân","tag":"Nhặt được vật quý ở nơi bất ngờ.","story":"Bạn từng cúi nhặt chiếc lá vàng cạnh giếng làng đem ép vào sách. Hôm sau, mặt sau lá hiện lên bản đồ dẫn đến một gốc cây giấu linh dược."}],"regen":[{"name":"Xuân Mộc Sinh Cơ","tag":"Vết thương khép miệng nhanh.","story":"Bạn bị gai yêu đằng rạch sâu bàn tay lúc hái củi. Đến khi chạy về nhà lấy vải băng, vết cắt đã khép lại, chỉ còn vệt xanh nhạt như gân lá."},{"name":"Huyết Noãn Hoàn Sinh","tag":"Khí huyết mau phục hồi sau giao chiến.","story":"Bạn té vào ổ chim lửa non trên vách núi và bị bỏng cả cánh tay. Sáng hôm sau, lớp da mới đã mọc dưới băng vải, ấm như vừa phơi nắng."},{"name":"Linh Tuyền Tái Cốt","tag":"Thương thế hồi phục lạ thường.","story":"Thuở bé, bạn uống nước từ mạch suối ngầm sau chùa hoang khi đang sốt mê man. Từ đó, những vết bầm trên người bạn thường tan trước lúc mẹ kịp sắc thuốc."}],"shadow":[{"name":"Minh Hà Dư Âm","tag":"Dễ gọi và thu phục vong linh.","story":"Bạn sinh vào đêm sông Minh Hà trong truyền thuyết được tế lễ ở làng. Lúc lên sáu, bạn gọi tên con chó đã chết bên mộ, và bóng nó ngoan ngoãn theo bạn về."},{"name":"Quỷ Đăng Đồng Tử","tag":"Âm hồn dễ nghe lời sai khiến.","story":"Bạn lạc trong nghĩa địa, ôm chiếc đèn giấy tắt lửa qua một đêm mưa. Sáng ra, ba đốm hồn hỏa vẫn lặng lẽ soi đường sau gót chân bạn."},{"name":"Ảnh Chủ Mệnh Cách","tag":"Bóng tối và xác linh dễ quy phục.","story":"Hồi nhỏ, bóng bạn từng tách khỏi chân trên vách tường miếu cổ. Nó kéo bạn tránh một thanh xà rơi, rồi dẫn theo chiếc bóng của hộ vệ đá đứng chờ bạn ra lệnh."}],"ward":[{"name":"Cửu Tử Dư Sinh","tag":"Mệnh cứng, khó mất mạng.","story":"Bạn từng bị lũ cuốn khỏi cầu Trấn Lạc Hà lúc năm tuổi. Ba ngày sau, ngư dân tìm thấy bạn ngủ yên trong hốc thuyền lật, tay vẫn nắm chặt chiếc kẹo mạch nha."},{"name":"Thiên Hộ Tàn Mệnh","tag":"Qua hiểm cảnh vẫn sống sót.","story":"Bạn đứng dưới gốc tùng khi lôi kiếp bất ngờ giáng xuống sườn núi. Cây cháy thành than, còn bạn tỉnh dậy giữa vòng rễ chưa bén lửa."},{"name":"Bất Tận Mệnh Đăng","tag":"Sinh cơ ngoan cường nơi tuyệt địa.","story":"Thuở bé, bạn mắc kẹt trong hầm băng suốt bảy ngày. Khi cửa hầm mở, ngọn đèn dầu bên cạnh đã tắt từ lâu, riêng hơi thở bạn vẫn đều như lúc ngủ."}],"trade":[{"name":"Kim Thiệt Thương Tài","tag":"Mặc cả khéo, tiền bạc dễ tụ.","story":"Bạn phụ mẹ bán trà ở Trấn Lạc Hà từ năm sáu tuổi. Một câu chuyện về lá trà hái trước bình minh của bạn khiến khách tự nguyện trả thêm hai đồng."},{"name":"Tụ Bảo Đồng Tâm","tag":"Biết nhìn hàng, buôn bán có lời.","story":"Bạn đổi ba viên sỏi sáng lấy chiếc chuông đồng cũ trong phiên chợ quê. Về nhà, bạn rửa sạch bùn và phát hiện đó là pháp khí còn dùng được."},{"name":"Bách Khách Hữu Duyên","tag":"Dễ kết mối hàng, kiếm tiền thuận lợi.","story":"Bạn từng chia nửa chiếc bánh cho một thương nhân lạc đường giữa trời tuyết. Từ đó, đoàn buôn của ông luôn ghé nhà bạn trước mỗi chuyến lên núi."}],"craft":[{"name":"Xảo Thủ Linh Công","tag":"Chế tác tinh xảo, ít hao vật liệu.","story":"Bạn lớn lên cạnh lò rèn, dùng mảnh sắt vụn làm chiếc khóa đầu tiên lúc bảy tuổi. Ổ khóa nhỏ ấy giữ được cửa kho qua cả đêm yêu thú phá làng."},{"name":"Bách Nghệ Mộc Tâm","tag":"Khéo tay với gỗ, thuốc và khí cụ.","story":"Bạn theo ông vào rừng đốn củi, nhìn vân gỗ mà chọn đúng thớ dễ chẻ. Về nhà, bạn còn dùng vỏ cây thơm nấu nước rửa sạch vết thương cho ông."},{"name":"Diệu Chỉ Thành Đan","tag":"Bào chế và sửa chữa hiệu quả.","story":"Bạn từng nhặt những lá thuốc bị Dược Vương Cốc loại bỏ. Dưới chiếc cối mẻ của bà, chúng thành cao trị bỏng khiến cả xóm kéo đến xin."}],"lead":[{"name":"Quần Tinh Hướng Bắc","tag":"Đồng đội tin tưởng, dễ quy tụ.","story":"Bạn dẫn đám trẻ lạc khỏi Vạn Thú Sơn Mạch bằng cách lần theo sao Bắc Đẩu. Từ đó, hễ gặp ngã rẽ, chúng đều chờ bạn đi trước."},{"name":"Nghĩa Khí Dẫn Đường","tag":"Dễ kết giao, khiến người khác an lòng.","story":"Bạn đứng chắn cửa kho thóc khi lũ về, nhường chỗ khô cho người già và trẻ nhỏ. Sáng hôm sau, cả làng tự đến giúp bạn dựng lại mái nhà."},{"name":"Thanh Phong Minh Chủ","tag":"Có uy tín tự nhiên trong đội ngũ.","story":"Thuở bé, bạn chia nhóm bạn thành hàng để cứu những giỏ thuốc trôi trên suối. Không ai bảo ai, cả đám làm theo tiếng gọi của bạn giữa dòng nước xiết."}],"slayer":[{"name":"Trảm Hùng Chi Mệnh","tag":"Đối mặt cường địch càng sắc bén.","story":"Bạn từng theo thợ săn đuổi một con hổ yêu già vào hang. Giữa tiếng gầm, bạn nhận ra chân trái nó khập khiễng và chỉ đúng chỗ để mọi người hạ nó."},{"name":"Liệp Vương Huyết Nhãn","tag":"Giỏi săn tinh anh và thủ lĩnh.","story":"Năm chín tuổi, bạn thấy con sói đầu đàn luôn đi sau bầy để che vết thương ở sườn. Bạn báo cho cha đổi hướng bẫy, cứu cả đàn dê khỏi một đêm tai họa."},{"name":"Nghịch Cường Kiếm Cốt","tag":"Gặp kẻ mạnh vẫn tìm được đường thắng.","story":"Bạn thường đấu kiếm gỗ với vị sư huynh lớn gấp đôi mình. Sau mười lần ngã xuống sân, bạn ghi nhớ nhịp thở trước đòn nặng nhất của huynh ấy và đánh trúng cổ tay."}],"fury":[{"name":"Huyết Nộ Cuồng Tâm","tag":"Càng trọng thương càng hung mãnh.","story":"Bạn bị sói yêu cắn rách vai khi bảo vệ em nhỏ. Máu thấm đỏ áo, nhưng mỗi lần nó lao tới, bạn lại đánh mạnh hơn, đến khi nó bỏ chạy."},{"name":"Thương Huyết Phệ Chiến","tag":"Đòn đánh hút sinh lực khi bị thương.","story":"Thuở bé, bạn bị yêu đằng quấn chặt trong rừng. Khi gai đâm vào tay, bạn giật đứt dây leo và thấy máu mình ngừng chảy lúc nhựa xanh của nó khô đi."},{"name":"Xích Diễm Phản Kích","tag":"Máu đổ càng nhiều, chiến ý càng cao.","story":"Bạn ngã vào bếp than trong lần làng bị thú triều tập kích. Cánh tay bỏng rát, bạn vẫn vung gậy đánh bật từng con thú, rồi chỉ thấy sức mình trở lại khi chúng gục xuống."}],"mind":[{"name":"Tâm Hồ Vô Ba","tag":"Tĩnh tâm để hồi phục linh lực.","story":"Bạn ngồi câu bên Hồ Tẩy Kiếm từ thuở bé, có khi cả ngày không động cần. Một lần linh khí cạn sau buổi tập, bạn chỉ nhắm mắt nghe nước vỗ bờ đã thấy khí mạch đầy lại."},{"name":"Thiền Tức Quy Nguyên","tag":"Bình thản giúp năng lượng hồi nhanh.","story":"Bạn từng bị nhốt nhầm trong phòng chuông chùa giữa cơn bão. Thay vì khóc, bạn đếm từng tiếng mưa trên mái ngói và cảm thấy hơi thở mang linh khí trở về."},{"name":"Minh Kính Tĩnh Khí","tag":"Giữ lòng yên để tích tụ linh khí.","story":"Hồi nhỏ, bạn lau chiếc gương đồng cho bà mỗi sáng, đến khi mặt gương sáng như nước. Ngày đầu tập pháp thuật, bạn phát hiện chỉ cần tâm không gợn, linh lực hao đi sẽ mau tụ lại."}],"frail":[{"name":"Bạc Mệnh Liễu Thân","tag":"Khí huyết mỏng, khó chịu thương.","story":"Bạn sinh giữa mùa tuyết, lớn lên với bát thuốc đặt thường trực bên giường. Một lần đuổi theo diều giấy qua sân, bạn ho ra máu và phải nằm dưỡng bệnh suốt nửa tháng."},{"name":"Ngọc Cốt Dễ Vỡ","tag":"Thân thể yếu, ít sinh lực.","story":"Thuở bé, bạn chỉ trượt chân trên bậc thềm rêu mà đã gãy xương cổ tay. Từ đó, mỗi buổi luyện quyền đều phải dừng sớm, nhìn bạn đồng môn tập tiếp dưới nắng."},{"name":"Hàn Mạch Tiểu Thể","tag":"Dễ kiệt sức khi chịu đòn.","story":"Bạn từng ngâm mình trong nước lũ lạnh để giữ em khỏi trôi. Em bình an, còn bạn mang chứng run rẩy mỗi khi trúng đòn, phải nghỉ lâu hơn người khác mới hồi sức."}],"slow":[{"name":"Trầm Cước Như Sơn","tag":"Chạy chậm, khó đuổi kịp mục tiêu.","story":"Bạn bị xe bò cán qua bàn chân lúc nhỏ, may giữ được xương nhưng gân chẳng còn linh hoạt. Từ đó, mỗi lần cả nhóm chạy lên núi, bạn luôn tới sau cùng."},{"name":"Nê Bộ Nan Hành","tag":"Di chuyển ì ạch, né tránh chậm.","story":"Bạn từng sa vào đầm lầy ở Vạn Thú Sơn Mạch và phải chờ đến sáng mới được kéo ra. Hàn khí ngấm sâu khiến chân bạn nặng như dính bùn, gặp thú dữ thường phải tìm chỗ núp trước."},{"name":"Ốc Hành Mệnh","tag":"Thân pháp chậm, dễ bị bắt kịp.","story":"Thuở bé, bạn mang đôi giày sắt gia truyền để nắn lại dáng đi. Chân dần thẳng, nhưng bước chạy vẫn chậm; ngay cả con ngỗng trước sân cũng thường rượt kịp bạn."}],"glutton":[{"name":"Thao Thiết Tiểu Phúc","tag":"Mau đói, cần nhiều lương thực.","story":"Bạn ăn sạch nồi cháo cả nhà ngay sau buổi nhập môn trúc cơ đầu tiên. Từ ấy, linh khí vừa vận chuyển là bụng bạn lại réo vang, tiền dành dụm thường hết vào gạo."},{"name":"Vô Đáy Đan Điền","tag":"Ăn nhiều, đói nhanh khi vận công.","story":"Bạn từng nuốt nhầm hạt linh cốc chưa nấu trong kho Dược Vương Cốc. Nó không hại mạng, nhưng từ đó một bữa cơm của bạn bằng ba người, thiếu ăn là tay chân bủn rủn."},{"name":"Phạn Nang Truy Mệnh","tag":"Phải tiếp tế thường xuyên.","story":"Thuở bé, bạn đi hái thuốc mà ăn hết phần lương khô trước khi lên tới lưng núi. Đến chiều, bạn đói lả bên gốc tùng và phải đổi viên linh thạch duy nhất lấy bánh."}],"unlucky":[{"name":"Ô Vân Trùm Đỉnh","tag":"Vận rủi đeo bám, chiến lợi phẩm kém.","story":"Bạn nhặt được chiếc hộp ngọc đầu tiên trong đời bên bờ suối. Vừa mở ra, viên đan duy nhất bên trong đã mục thành tro; từ ấy, rương tốt đến tay bạn thường chỉ còn đồ vụn."},{"name":"Không Túi Số Đen","tag":"Khó gặp đồ quý sau giao chiến.","story":"Bạn theo cha đi hái linh chi, lần nào chỉ vào cây lớn nhất thì dưới gốc cũng rỗng không. Đến tuổi tu luyện, phần chiến lợi phẩm bạn bốc thăm thường là túi da rách."},{"name":"Mệnh Gặp Lá Úa","tag":"May mắn thấp, ít nhặt được vật tốt.","story":"Thuở bé, bạn đào đúng chỗ mọi người đồn chôn linh thạch, nhưng chỉ thấy chiếc thìa gỉ. Đến nay, mỗi lần đồng đội chia vật phẩm, món trong tay bạn vẫn hay là thứ kém giá nhất."}],"clumsy":[{"name":"Lệch Tiễn Đồng Tâm","tag":"Bắn kém chính xác, lên dây chậm.","story":"Bạn tập bắn lá sen ở Hồ Tẩy Kiếm suốt một mùa hè, nhưng tên cứ cắm xuống bùn. Mỗi lần lên dây cung, ngón tay lại vướng nút, khiến con cá dưới lá kịp lặn mất."},{"name":"Nỏ Chờ Trăng Lặn","tag":"Nạp vũ khí tầm xa rất chậm.","story":"Bạn được giao trông nỏ săn trước cổng làng lúc tám tuổi. Đến khi bạn lắp xong mũi tên đầu tiên, con thỏ đã ăn hết rau rồi chạy về rừng."},{"name":"Phi Châm Lạc Hướng","tag":"Vũ khí tầm xa dễ trượt mục tiêu.","story":"Bạn từng ném phi châm cứu một con chim mắc lưới, nhưng châm lại ghim vào quả bầu phía sau. Con chim vẫn được cứu, còn từ đó bạn tốn gấp đôi ám khí mỗi buổi tập."}],"weak":[{"name":"Nhu Oản Vô Lực","tag":"Đòn cận chiến kém uy lực.","story":"Bạn được bà dạy thái dược từ nhỏ, cổ tay quen nâng lá hơn cầm kiếm. Buổi đầu bổ củi luyện lực, bạn vung rìu mười lần mới làm sứt nổi một khúc gỗ."},{"name":"Miên Quyền Bất Phá","tag":"Sức tay yếu, khó phá giáp gần.","story":"Thuở bé, bạn đánh nhau với con ngỗng giữ sân và thua đến rơi cả guốc. Lớn lên, quyền của bạn vẫn nhẹ; muốn hạ đối thủ mặc giáp phải nhờ đến pháp thuật."},{"name":"Lục Trúc Nhuyễn Tí","tag":"Cận chiến yếu, cần tránh đấu sức.","story":"Bạn từng bị bệnh lâu ngày sau một trận sốt trên Thanh Vân Sơn. Khỏi bệnh, bạn cầm nổi kiếm gỗ nhưng không đỡ nổi cú bổ mạnh, nên luôn phải nhường đường khi luyện đối kiếm."}],"dull":[{"name":"Mộc Ngộ Trì Khai","tag":"Lĩnh hội chậm, tích lũy kinh nghiệm ít.","story":"Bạn học khẩu quyết nhập môn dưới gốc hòe suốt ba tháng mà vẫn đảo nhầm hai câu. Sư tỷ phải vẽ từng nét lên bảng gỗ, còn bạn vì thế tiến cảnh chậm hơn bạn đồng môn."},{"name":"Nhất Văn Tam Quên","tag":"Học lâu nhớ ít, tu hành chậm.","story":"Thuở bé, bạn ghi tên các loại linh thảo lên tay áo để giúp mẹ, rồi giặt mất sạch trước buổi hái thuốc. Đến nay, mỗi bài học bạn thường phải luyện thêm nhiều lượt mới nhớ chắc."},{"name":"Độn Tâm Hậu Giác","tag":"Khó rút kinh nghiệm từ việc đã qua.","story":"Bạn từng mắc cùng một chiếc bẫy dây của sư huynh ba ngày liên tiếp. Dù đã tháo bẫy tận tay, bạn vẫn chậm nhận ra mẹo đặt nó và tốn thêm thời gian để học mỗi chiêu mới."}],"dark":[{"name":"Dạ Ảnh Kinh Hồn","tag":"Sợ bóng tối, chiến lực giảm về đêm.","story":"Bạn lạc trong hầm mỏ khi đèn dầu tắt, nghe tiếng nước nhỏ như bước chân sau lưng. Từ đó, trời vừa tối là tay cầm kiếm run, những đòn đánh cũng chậm hẳn đi."},{"name":"Vô Nguyệt Khiếp Tâm","tag":"Đêm tối khiến ra đòn kém ổn định.","story":"Thuở bé, bạn thấy một bóng người đứng ngoài cửa sổ vào đêm không trăng; sáng ra chỉ còn dấu chân ướt. Nỗi sợ ấy theo bạn lớn lên, khiến mỗi trận đánh ban đêm đều hao sức hơn."},{"name":"Ám Trung Lạc Phách","tag":"Thiếu ánh sáng là dễ mất bình tĩnh.","story":"Bạn từng ngủ quên trong miếu bỏ hoang, tỉnh dậy giữa đêm khi đèn thờ phụt tắt. Từ ấy, hễ giao chiến nơi tối tăm, bạn hay đánh hụt và phải dựa vào đồng đội soi đường."}],"poor":[{"name":"Tụ Tài Vô Duyên","tag":"Tiền kiếm được thường ít ỏi.","story":"Bạn phụ bán thuốc ở Trấn Lạc Hà, nhưng trận mưa đầu mùa làm ướt gần hết số hàng. Lớn lên, những việc bạn nhận vẫn thường trả công bèo bọt, khiến túi tiền khó đầy."},{"name":"Không Hầu Bao","tag":"Thu nhập thấp, khó dành dụm.","story":"Thuở bé, bạn đem bó củi tốt nhất ra chợ đúng ngày ai cũng mang củi đến. Bán rẻ mãi mới hết, bạn chỉ đủ mua một chiếc bánh; vận kiếm tiền về sau cũng chẳng khá hơn."},{"name":"Bạc Phận Đồng Tiền","tag":"Làm nhiều mà nhận thù lao ít.","story":"Bạn từng giúp đoàn buôn kéo xe qua đèo, đến nơi mới biết họ chỉ còn vài đồng lẻ trả công. Từ đó, mỗi chuyến làm thuê bạn hay nhận phần ít nhất, đan dược cũng phải tính từng viên."}],"leak":[{"name":"Tỏa Linh Tàn Mạch","tag":"Khí mạch tắc nghẽn, linh lực ít.","story":"Bạn ngã xuống khe băng lúc nhỏ, hàn khí bám vào một đoạn linh mạch. Mỗi lần vận công, linh khí dồn lại đau nhói rồi tản mất, khiến bạn khó thi triển nhiều pháp thuật."},{"name":"Khô Tuyền Đan Điền","tag":"Linh lực dự trữ thấp, mau cạn.","story":"Thuở bé, bạn dùng sức truyền khí cứu cây linh thảo sắp chết trong vườn thuốc. Cây sống lại, nhưng từ đó đan điền bạn chứa rất ít linh lực, luyện thuật vài lượt đã phải nghỉ."},{"name":"Đoạn Khí Chi Mạch","tag":"Mana ít do mạch khí khó thông.","story":"Bạn trúng độc châm của yêu phong khi còn chăn dê ở sườn núi. Dược sư cứu được mạng, song vết thương để lại một nút thắt trong khí mạch, khiến linh lực lên tay yếu ớt."}],"feud":[{"name":"Huyết Cừu Truy Mệnh","tag":"Mang thù cũ, luôn có kẻ truy sát.","story":"Bạn trốn dưới sàn nhà đêm gia tộc bị tà tu diệt môn và nhìn thấy ngọc bội trên lưng kẻ cầm đầu. Giờ hắn biết bạn còn sống; mỗi lần ngọc bội ấy xuất hiện gần trấn, bạn phải bỏ dở hành trình."},{"name":"Nợ Máu Tàng Kiếm","tag":"Kẻ thù cũ không ngừng tìm đến.","story":"Thuở bé, bạn nhặt thanh kiếm gãy của phụ thân bên Hồ Tẩy Kiếm. Chủ nhân vết kiếm trên đó vẫn sai người dò tung tích bạn, buộc bạn phải canh cửa mỗi đêm và tránh những con đường lớn."},{"name":"Oán Ấn Trên Vai","tag":"Dấu thù khiến sát thủ lần theo.","story":"Bạn bị kẻ áo đen đóng một ấn đỏ lên vai khi cứu sư muội khỏi tay hắn. Ấn không xóa được; cứ qua một mùa trăng, tay sai của hắn lại tìm đến, khiến nơi bạn trú chân chẳng được yên."}],"lone":[{"name":"Cô Tinh Chiếu Mệnh","tag":"Khó kết thân, đồng hành ít người.","story":"Bạn sống một mình trong tháp canh cũ sau khi làng dời đi vì thú triều. Khi xuống chợ, bạn quen im lặng đến mức người khác tưởng bạn giấu điều gì, rồi tránh ngồi cùng bàn."},{"name":"Hàn Diện Ly Quần","tag":"Vẻ lạnh lùng khiến người khác dè chừng.","story":"Thuở bé, bạn luôn đứng gác ngoài phòng thuốc khi mẹ chữa bệnh, không dám làm phiền ai. Thói quen nhìn người mà chẳng nói khiến bạn khó có bạn đồng hành, dù lòng bạn muốn gần họ."},{"name":"Độc Hành Bóng Kiếm","tag":"Khó gây tin cậy, thường phải đi một mình.","story":"Bạn từng bị cả nhóm đổ oan làm mất linh thạch trong chuyến hái thuốc đầu tiên. Từ đó, bạn giữ mọi chuyện trong lòng; gặp người mới, sự dè dặt ấy khiến họ cũng chẳng dám thân thiết."}]},"sl":{"bone":[{"name":"Xương Thép Cổng Vỡ","tag":"Chịu đòn như tường thành.","story":"Bạn từng bị cánh Cổng hạng D sập xuống vai khi còn nhỏ. Người ta kéo bạn ra khỏi đống bê tông, còn xương bạn chẳng nứt lấy một đường."},{"name":"Máu Dày Bạch Hổ","tag":"Sức bền và sinh lực dồi dào.","story":"Bạn lớn lên sau hàng rào tập luyện của Bang Hội Bạch Hổ, nơi lũ trẻ thi nhau chịu những cú đấm vào bao cát. Bao cát rách trước khi bạn chịu xin nghỉ."},{"name":"Da Đồng Ga Ngầm","tag":"Đứng vững giữa đòn đánh.","story":"Bạn bị quái thú húc văng vào cột sắt ở Ga ngầm Trung Tâm năm tám tuổi. Cột móp một vệt sâu, còn bạn chỉ phủi bụi trên áo."}],"swift":[{"name":"Gót Chân Gió Lùa","tag":"Chạy nhanh, né đòn linh hoạt.","story":"Bạn từng chạy xuyên chợ đêm để thoát một con goblin lọt Cổng. Nó chỉ ngoạm được chiếc dép bạn bỏ lại trên bậc thang."},{"name":"Bước Lướt Sương Mù","tag":"Di chuyển nhẹ và khó bị bắt kịp.","story":"Bạn lớn lên trên Đảo Sương Mù, ngày nào cũng chạy qua cầu gỗ trơn để kịp chuyến phà. Đến năm mười tuổi, bạn nhắm mắt vẫn tránh được từng tấm ván mục."},{"name":"Nhịp Chân Báo Động","tag":"Phản xạ né tránh sắc bén.","story":"Bạn thường ngủ cạnh còi báo Cổng của khu phố. Mỗi lần còi rú, bạn đã ôm em lao xuống hầm trước khi người lớn kịp mở cửa."}],"eye":[{"name":"Mắt Ngắm Vết Nứt","tag":"Dễ nhận ra điểm yếu mục tiêu.","story":"Bạn từng ngồi hàng giờ xem cha vá tường chắn Cổng. Giữa trăm vết búa, bạn luôn chỉ đúng viên gạch sắp vỡ."},{"name":"Đồng Tử Ưng Đêm","tag":"Ngắm bắn chính xác từ xa.","story":"Bạn tập ném sỏi vào quả thông trên mái nhà mỗi chiều mất điện. Một hôm, bạn bắn trúng con mắt đỏ của quái vật vừa ló khỏi Cổng."},{"name":"Tia Nhìn Kết Liễu","tag":"Đòn đánh dễ trúng chỗ hiểm.","story":"Bạn thấy chấm sáng bé như đầu kim trên gáy con nhện Cổng khi mới chín tuổi. Mũi tên đồ chơi bạn bắn vào đó đã khiến nó đổ gục."}],"might":[{"name":"Nắm Đấm Nứt Đá","tag":"Cận chiến mang sức nặng vượt trội.","story":"Bạn lớn lên phụ mẹ dỡ gạch từ những tòa nhà bị Cổng tàn phá. Năm mười hai tuổi, bạn lỡ bóp vụn một viên gạch còn nguyên trong tay."},{"name":"Vai Gánh Cổng Sắt","tag":"Sức mạnh cơ bắp bẩm sinh.","story":"Bạn từng nhấc cửa cuốn mắc kẹt để cả lớp chạy khỏi đàn quái. Sau đó, ba người thợ mới hạ nổi cánh cửa bạn đã nâng."},{"name":"Huyết Lực Bạch Hổ","tag":"Đòn cận chiến đầy uy lực.","story":"Bạn được một thợ săn Bạch Hổ dạy đấm bao cát lúc còn bé. Buổi đầu tiên, đường chỉ của bao bật tung, cát rơi trắng cả sàn."}],"sage":[{"name":"Óc Sáng Hệ Thống","tag":"Học kỹ năng và trưởng thành nhanh.","story":"Bạn đọc lén bảng kỹ năng của chị mỗi tối dưới chăn. Sáng hôm sau, bạn đã giải được bài thử thức tỉnh mà chị mất cả tuần mới hiểu."},{"name":"Một Lần Là Nhớ","tag":"Tiếp thu kinh nghiệm vượt trội.","story":"Bạn chỉ xem thợ săn vẽ trận pháp trên nền xi măng đúng một lần. Về nhà, bạn dùng phấn tái hiện nó đến từng nét đứt."},{"name":"Ngộ Tính Sao Rơi","tag":"Nhanh tìm ra quy luật kỹ năng.","story":"Bạn từng nhặt mảnh tinh thạch Cổng sau sân trường và nhìn ánh sáng chạy bên trong. Tối ấy, bạn tự hiểu cách dẫn mana qua đầu ngón tay."}],"mana":[{"name":"Giếng Mana Xanh","tag":"Trữ lượng mana dồi dào.","story":"Bạn sốt cao trong đêm một Cổng mở cạnh bệnh viện. Nước trong ly đầu giường phát sáng suốt ba ngày vì mana tràn khỏi cơ thể bạn."},{"name":"Mạch Nguồn Bất Tận","tag":"Dùng kỹ năng lâu hơn thường lệ.","story":"Bạn từng chơi trò thắp sáng tinh thạch với lũ trẻ trong ngõ. Khi đèn của chúng tắt hết, viên đá trong tay bạn vẫn sáng tới bình minh."},{"name":"Tim Đập Linh Triều","tag":"Mana dâng mạnh theo nhịp tim.","story":"Bạn chào đời đúng lúc còi báo Cổng vang khắp khu phố. Bà đỡ kể mỗi nhịp tim bạn lại làm những lá bùa trên cửa rung lên."}],"fortune":[{"name":"Tay Nhặt Sao Rơi","tag":"Dễ tìm được chiến lợi phẩm quý.","story":"Bạn nhặt một viên đá lấp lánh dưới ghế xe buýt khi còn bé. Hiệp Hội xác nhận đó là tinh thạch hiếm bị thất lạc ba năm."},{"name":"Lộc Sau Cánh Cổng","tag":"Hay gặp món đồ tốt bất ngờ.","story":"Bạn trốn mưa dưới mái kho cạnh Cổng hạng E. Một cái rương quái vật bỏ quên nằm đúng chỗ bạn đặt chân."},{"name":"Đồng Xu May Mắn","tag":"Vận may thường đứng về phía bạn.","story":"Bạn tìm được đồng xu cổ trong khe máy bán nước và giữ nó từ năm chín tuổi. Hôm cả lớp bốc thăm vật phẩm, chiếc chìa khóa hiếm rơi vào tay bạn."}],"regen":[{"name":"Da Liền Trước Bình Minh","tag":"Vết thương hồi phục rất nhanh.","story":"Bạn ngã khỏi hàng rào thép gai hồi nhỏ, để lại một đường rách dài trên tay. Sáng hôm sau, y tá chỉ tìm thấy vệt da hồng mỏng."},{"name":"Hơi Thở Tái Sinh","tag":"Cơ thể tự chữa lành lạ thường.","story":"Bạn bị quái chuột cắn trong lần sơ tán khỏi Cổng. Trước khi mẹ tìm được băng gạc, dấu răng đã khép kín."},{"name":"Máu Khép Miệng Vết","tag":"Nhanh hồi phục sau giao chiến.","story":"Bạn từng đứt tay sâu khi gọt lõi tinh thạch cùng ông. Giọt máu chưa kịp rơi khỏi bàn thì da đã liền lại."}],"shadow":[{"name":"Đứa Trẻ Không Bóng","tag":"Dễ gọi và thu phục bóng tối.","story":"Bạn sinh ra trong đêm Bệnh viện Thánh Tâm mất điện vì Cổng mở. Dưới ánh nến, mọi người đều có bóng trên tường, trừ bạn."},{"name":"Lời Ru Từ Cõi Chết","tag":"Linh hồn dễ nghe lời bạn.","story":"Bạn thường ngủ ở nhà tang lễ nơi bà làm việc. Năm bảy tuổi, bạn gọi tên một người đã khuất, và bóng ông lặng lẽ kéo chăn cho bạn."},{"name":"Ấn Chủ Bóng Tàn","tag":"Có duyên với binh đoàn bóng tối.","story":"Bạn lạc trong hầm trú ẩn sau một trận quái tập kích. Những bóng người trên vách đứng dậy dẫn bạn qua lối thoát, rồi quỳ xuống khi trời sáng."}],"ward":[{"name":"Mệnh Qua Cửa Tử","tag":"Dễ sống sót trước hiểm nghèo.","story":"Bạn bị kẹt ba ngày dưới Ga ngầm Trung Tâm sau vụ sập Cổng. Khi đội cứu hộ đến, đống đổ nát quanh bạn vẫn chưa rơi thêm một viên gạch."},{"name":"Số Mệnh Chưa Gạch","tag":"Thoát chết trong gang tấc.","story":"Bạn từng rơi khỏi cầu thang thoát hiểm lúc sáu tuổi. Một tấm biển Hiệp Hội vừa bung ốc đã đỡ bạn trước mặt đường."},{"name":"Bùa Sống Sót","tag":"Bền mạng trước tai ương.","story":"Bạn giữ lá bùa giấy mẹ gấp trong túi áo từ bé. Đêm quái vật quét qua khu nhà, mọi cánh cửa đều vỡ trừ cửa phòng bạn."}],"trade":[{"name":"Miệng Cười Ra Vàng","tag":"Buôn bán khéo, dễ sinh lời.","story":"Bạn bán lại những viên bi cũ ở cổng trường để mua thuốc cho em. Cuối tuần, túi bạn đã đủ tiền và còn dư một nắm xu."},{"name":"Mắt Định Giá","tag":"Nhìn ra giá trị món hàng.","story":"Bạn từng theo dì đến chợ đồ thợ săn, nơi ai cũng chê một con dao sứt mẻ. Bạn mua nó bằng tiền ăn sáng; hôm sau, thợ rèn tìm ra lõi tinh thạch trong cán."},{"name":"Lộc Quầy Ga Ngầm","tag":"Giao dịch thuận lợi, tiền đến dễ.","story":"Bạn phụ cha bán nước ở Ga ngầm Trung Tâm từ nhỏ. Chỉ cần bạn đứng quầy, cả những thợ săn vội lên tàu cũng quay lại mua thêm."}],"craft":[{"name":"Bàn Tay Tinh Thạch","tag":"Chế tạo vật phẩm hiệu quả hơn.","story":"Bạn nhặt mảnh tinh thạch vỡ sau xưởng rèn và ghép chúng thành chiếc đèn nhỏ. Nó sáng suốt đêm dù thợ cả bảo nguyên liệu đã hỏng."},{"name":"Dao Gọt Không Trượt","tag":"Gia công chính xác, ít hao vật liệu.","story":"Bạn học đẽo cán rìu trên đống gỗ vụn sau nhà. Đến năm mười tuổi, từng nhát dao của bạn đều dừng sát vạch phấn."},{"name":"Tay Thuốc Lá Rừng","tag":"Pha thuốc và xử lý nguyên liệu khéo.","story":"Bạn theo bà hái dược thảo bên rìa Cổng hạng E. Mẻ thuốc đầu tay của bạn cứu được con chó bị quái cào, không phí một chiếc lá."}],"lead":[{"name":"Ngọn Cờ Giữa Loạn","tag":"Đồng đội dễ tin và làm theo.","story":"Bạn từng dẫn cả lớp thoát khỏi trường khi chuông báo Cổng vang lên. Giữa hành lang đầy khói, mọi đứa trẻ đều nắm chặt vạt áo bạn."},{"name":"Tiếng Gọi Tập Hợp","tag":"Dễ kết thân và quy tụ người khác.","story":"Bạn thường rủ những đứa trẻ bị bỏ lại ở sân chung cư lập đội tuần tra. Chẳng ai được trả công, nhưng chiều nào chúng cũng chờ bạn đến."},{"name":"Lưng Đứng Trước Nhất","tag":"Truyền lòng can đảm cho đồng đội.","story":"Bạn đứng chắn trước em mình khi một con quái lạc vào khu sơ tán. Thấy bạn không lùi, những người lớn phía sau cũng cầm gậy bước lên."}],"slayer":[{"name":"Nanh Săn Đầu Đàn","tag":"Sắc bén khi đối đầu kẻ mạnh.","story":"Bạn từng nhận ra con sói Cổng lớn nhất luôn đi sau cả bầy. Khi nó lao tới sân trường, bạn hét đúng lúc để đội thợ săn chặn đầu nó."},{"name":"Kẻ Nhìn Lên Đỉnh","tag":"Gặp boss càng dễ tập trung.","story":"Bạn không nhìn đám quái nhỏ trong buổi tập mô phỏng đầu đời. Mắt bạn chỉ bám vào hình chiếu boss và khoảng trống dưới lớp giáp cổ nó."},{"name":"Dấu Ấn Săn Vua","tag":"Đòn đánh hiểm trước tinh anh.","story":"Bạn tìm thấy xác con quái đầu đàn bên rìa Cổng lúc còn bé. Thay vì bỏ chạy, bạn ghi nhớ vết thương duy nhất trên lớp vảy dày của nó."}],"fury":[{"name":"Máu Nóng Trên Lưỡi","tag":"Càng bị thương càng hung hãn.","story":"Bạn bị quái thú cào vai trong lần sơ tán đầu tiên. Cơn đau khiến bạn lao tới giằng chiếc túi cứu thương khỏi hàm nó thay vì bỏ chạy."},{"name":"Nộ Huyết Hồi Sinh","tag":"Chiến đấu có thể hút lại sinh lực.","story":"Bạn từng đánh bật con quái đang cắn bạn ở bãi xe. Máu nó dính lên vết thương, và sức lực vừa mất bỗng chảy ngược về tay."},{"name":"Cơn Giận Đỏ Thẫm","tag":"Trúng đòn càng đánh dữ dội.","story":"Bạn học đấu tay đôi với anh trai trong sân bê tông. Mỗi lần môi bật máu, cú đánh kế tiếp của bạn lại nặng hơn, đến mức anh phải giấu găng."}],"mind":[{"name":"Hồ Lặng Trong Tim","tag":"Bình tâm để hồi năng lượng.","story":"Bạn ngồi hàng giờ bên hồ bệnh viện chờ mẹ tan ca. Giữa tiếng còi báo Cổng, chỉ cần nhìn mặt nước phẳng, bạn lại thấy mana đầy lên."},{"name":"Hơi Thở Không Gợn","tag":"Giữ tĩnh lặng để phục hồi.","story":"Bạn học đếm hơi thở khi trốn cùng em trong hầm trú ẩn. Tiếng quái cào cửa nhỏ dần trong tai, còn sức lực trở lại từng nhịp."},{"name":"Tâm Sáng Giữa Mưa","tag":"Càng điềm tĩnh càng bền sức.","story":"Bạn từng ngồi thiền dưới mái hiên dột cùng ông ngoại. Nước mưa nhỏ lên vai lạnh buốt, nhưng viên tinh thạch trong tay bạn cứ sáng dần."}],"frail":[{"name":"Xương Mỏng Như Kính","tag":"Sinh lực thấp, dễ bị thương.","story":"Bạn gãy cổ tay chỉ vì ngã khỏi bậc thềm bệnh viện lúc nhỏ. Từ đó, một cú va nhẹ cũng buộc bạn tốn tiền băng nẹp và nghỉ tập."},{"name":"Hơi Thở Mỏng","tag":"Ít máu, khó chịu đòn.","story":"Bạn lớn lên giữa mùi thuốc sát trùng ở Bệnh viện Thánh Tâm. Một trận sốt nhẹ cũng khiến bạn nằm cả tuần, bỏ lỡ mọi buổi luyện tập."},{"name":"Da Giấy Trước Gió","tag":"Thể chất yếu ớt bẩm sinh.","story":"Bạn từng bị dây đeo ba lô cứa rách vai trên đường đi học. Đến nay, áo giáp nặng vẫn làm bạn bầm tím trước cả khi gặp quái."}],"slow":[{"name":"Bước Chân Chì","tag":"Di chuyển chậm chạp.","story":"Bạn luôn về cuối trong những cuộc chạy sơ tán ở trường. Cái giá là bạn phải nghe còi báo lâu hơn mọi người và thường cần ai đó quay lại đón."},{"name":"Gót Giày Dính Đất","tag":"Khó tăng tốc và né tránh.","story":"Bạn từng mắc kẹt đôi ủng trong bùn ở Đảo Sương Mù, nhìn chuyến phà cuối rời bến. Từ đó, dù mang giày nhẹ, bạn vẫn phải xuất phát sớm hơn người khác."},{"name":"Nhịp Chạy Lỡ Tàu","tag":"Chạy ì ạch, khó bắt kịp đội.","story":"Bạn đuổi theo đoàn thợ săn qua Ga ngầm Trung Tâm khi còn bé nhưng chỉ kịp thấy cửa tàu khép lại. Giờ mỗi cuộc truy kích đều khiến đồng đội phải chờ bạn."}],"glutton":[{"name":"Dạ Dày Hố Cổng","tag":"Nhanh đói, cần nhiều lương thực.","story":"Bạn ăn sạch nồi cơm cứu trợ sau một buổi chạy trốn quái hồi nhỏ. Từ đó, chuyến đi Cổng nào của bạn cũng tốn thêm một túi khẩu phần."},{"name":"Bụng Kêu Báo Động","tag":"Đói thường xuyên, khó tập trung.","story":"Bạn từng nghe bụng mình réo át tiếng giảng trong lớp huấn luyện thiếu niên. Nếu bỏ bữa, tay bạn run đến mức chẳng giữ nổi vũ khí."},{"name":"Cơn Khát Mana","tag":"Tiêu hao nhiều đồ ăn thức uống.","story":"Bạn uống cạn bình nước của cả đội trong chuyến dã ngoại gần Cổng hạng E. Bây giờ bạn luôn phải mang gấp đôi nước, đổi lại là chiếc ba lô nặng trĩu."}],"unlucky":[{"name":"Tay Trắng Sau Cổng","tag":"Chiến lợi phẩm thường kém.","story":"Bạn từng mở mười rương tập sự liên tiếp và chỉ thấy vỏ tinh thạch rỗng. Đến nay, đồng đội vẫn ngậm ngùi giành mở rương thay bạn."},{"name":"Số Đen Mưa Axit","tag":"Vận rủi bám theo đồ nhặt.","story":"Bạn nhặt được chiếc ô duy nhất trong ngày mưa trên Đảo Sương Mù; nó bung nan ngay khi bạn mở. Trong Cổng, món đồ bạn chọn cũng hay hỏng đúng lúc cần."},{"name":"Lộc Rơi Sang Bên","tag":"Hiếm khi nhận được vật phẩm tốt.","story":"Bạn bốc thăm cuối trong mọi buổi phát quà ở trại sơ tán. Phần còn lại luôn là món sứt mẻ, khiến bạn phải tốn tiền sửa trước khi dùng."}],"clumsy":[{"name":"Ngón Tay Kẹt Đạn","tag":"Nạp chậm, dùng vũ khí xa vụng về.","story":"Bạn làm rơi cả hộp đạn tập xuống cống trong buổi học bắn đầu tiên. Đến nay, mỗi lần nạp lại là đồng đội phải che chắn thêm cho bạn."},{"name":"Mũi Tên Lạc Gió","tag":"Khó bắn trúng mục tiêu xa.","story":"Bạn từng bắn tên vào bảng điểm của sân bên cạnh thay vì bia trước mặt. Cái giá là mỗi chuyến săn, bạn phải áp sát quái hơn dự tính."},{"name":"Tâm Ngắm Biết Chạy","tag":"Thiện xạ kém, thao tác chậm.","story":"Bạn nhìn con sốt ruột của cha mỗi lần lắp kính ngắm đồ chơi hồi nhỏ. Giờ mục tiêu thường chạy mất trước khi bạn chỉnh xong nòng súng."}],"weak":[{"name":"Nắm Đấm Bông","tag":"Đòn cận chiến kém uy lực.","story":"Bạn từng đấm bao cát trong lớp thiếu niên Bạch Hổ; bao chẳng nhúc nhích, còn cổ tay bạn sưng cả tối. Từ đó, bạn phải trông vào vũ khí hơn sức tay."},{"name":"Vai Không Gánh Nổi","tag":"Sức cơ bắp thấp.","story":"Bạn không nâng nổi chiếc khiên tập mà bạn bè cùng tuổi chuyền tay nhau. Mỗi trận cận chiến, bạn buộc phải chọn giáp nhẹ và chịu đòn ít hơn."},{"name":"Lưỡi Kiếm Nhẹ Tênh","tag":"Khó gây sát thương khi áp sát.","story":"Bạn vung kiếm gỗ vào hình nộm lúc nhỏ, để lại đúng một vết bụi. Đến nay, nếu quái áp sát, bạn phải đánh nhiều nhát hơn người khác mới hạ nổi nó."}],"dull":[{"name":"Bảng Kỹ Năng Mờ","tag":"Học chậm, nhận ít kinh nghiệm.","story":"Bạn chép đi chép lại một kỹ năng suốt mùa hè mà vẫn nhầm thứ tự kích hoạt. Cái giá là bạn thường lên cấp sau bạn bè dù luyện tập ngang họ."},{"name":"Đầu Óc Ngủ Gật","tag":"Tiếp thu kinh nghiệm chậm.","story":"Bạn từng nghe thầy giảng về lõi quái ba buổi liền rồi vẫn chỉ nhầm sang viên bi. Trong Cổng, bạn phải hỏi lại chỉ dẫn và bỏ lỡ cơ hội học nhanh."},{"name":"Một Bài Ba Mùa","tag":"Mất nhiều thời gian để thành thạo.","story":"Bạn tập cùng một thế kiếm từ mùa xuân đến lúc tuyết phủ sân trường. Khi bạn làm đúng, bạn tập đã học thêm ba chiêu, còn bạn vẫn phải luyện bù."}],"dark":[{"name":"Sợ Bóng Tắt Đèn","tag":"Chiến đấu kém trong bóng tối.","story":"Bạn từng bị nhốt nhầm trong kho bệnh viện khi mất điện. Từ đó, cứ đèn tắt là tay bạn run, và một cú đánh quen thuộc cũng dễ trượt."},{"name":"Đêm Có Mắt Đỏ","tag":"Ban đêm khó giữ bình tĩnh.","story":"Bạn thấy hai mắt quái sáng lên ngoài cửa sổ lúc tám tuổi. Dù nó đã bị diệt, đêm xuống bạn vẫn nhìn quanh thay vì nhìn mục tiêu trước mặt."},{"name":"Tim Run Dưới Trăng","tag":"Sức chiến đấu giảm về đêm.","story":"Bạn lạc đoàn sơ tán trong đường hầm tối ở Ga ngầm Trung Tâm. Từ đó, mỗi trận đánh ban đêm đều tốn thêm sức chỉ để ép mình bước tới."}],"poor":[{"name":"Túi Rỗng Bẩm Sinh","tag":"Tiền kiếm được thường ít.","story":"Bạn bán được viên tinh thạch đầu tiên lúc nhỏ thì phải dùng hết tiền sửa cửa nhà bị quái phá. Đến nay, khoản thưởng nào về tay bạn cũng nhanh chóng vơi đi."},{"name":"Lương Chưa Qua Đêm","tag":"Khó giữ tiền và tích lũy.","story":"Bạn lớn lên với chiếc ví luôn dành phần cho viện phí của mẹ. Mỗi món đồ kiếm được phải bán sớm lấy tiền thuốc, nên túi bạn hiếm khi đầy."},{"name":"Đồng Xu Cuối Cùng","tag":"Thu nhập thấp, chi tiêu chật vật.","story":"Bạn từng đếm từng đồng xu dưới ánh đèn bếp để mua vé tàu đi kiểm tra thức tỉnh. Giờ những việc bạn nhận thường trả ít, buộc bạn cân nhắc cả tiền ăn."}],"leak":[{"name":"Mạch Mana Nứt","tag":"Trữ lượng mana thấp.","story":"Bạn làm sáng tinh thạch thức tỉnh được đúng một nhịp rồi nó tắt phụt. Từ đó, bạn phải dành dụm mana cho từng kỹ năng, không thể đánh dài hơi."},{"name":"Giếng Cạn Trong Ngực","tag":"Nhanh cạn năng lượng.","story":"Bạn ngất sau lần đầu thử duy trì lá chắn cho con mèo bị quái đuổi. Một kỹ năng nhỏ cũng rút cạn sức, khiến bạn phải nghỉ giữa trận."},{"name":"Linh Khí Nghẽn Mạch","tag":"Mana khó lưu thông.","story":"Bạn thấy thầy cau mày khi dòng sáng trong phép đo thức tỉnh dừng giữa cổ tay. Đến nay, mỗi lần dùng phép bạn đều phải gắng sức mà vẫn yếu hơn người khác."}],"feud":[{"name":"Món Nợ Máu Cũ","tag":"Có kẻ thù luôn tìm đến.","story":"Bạn nhận diện kẻ đã bán thông tin nơi trú ẩn của gia đình khi còn nhỏ. Hắn thoát khỏi cuộc truy bắt, và giờ tay chân của hắn thường xuất hiện trên đường bạn đi."},{"name":"Dấu Săn Trên Vai","tag":"Bị một phe bí mật truy đuổi.","story":"Bạn tỉnh dậy sau vụ Cổng vỡ với một ký hiệu đỏ trên vai. Từ đó, những kẻ đeo mặt nạ luôn tìm bạn, buộc bạn phải đổi chỗ ở nhiều lần."},{"name":"Thù Nhà Phượng Hoàng","tag":"Oán cũ kéo theo hiểm họa.","story":"Bạn vô tình giữ chiếc huy hiệu của một thợ săn tử nạn trong vụ cháy Cổng. Kẻ muốn xóa chứng cứ đã thấy bạn cầm nó, và đến nay bạn vẫn không dám đi đường vắng."}],"lone":[{"name":"Bóng Đi Một Mình","tag":"Khó kết thân với đồng đội.","story":"Bạn từng là đứa duy nhất bước ra khỏi nhóm trẻ lạc trong Cổng hạng E. Từ đó, người khác nói nhỏ khi bạn đến gần, còn lời mời lập đội hiếm khi tới."},{"name":"Ghế Trống Bên Cạnh","tag":"Người khác thường dè chừng.","story":"Bạn làm chiếc bóng dưới chân bạn học cử động trong lúc thức tỉnh. Từ hôm ấy, chiếc ghế cạnh bạn luôn để trống, khiến việc tìm đồng đội khó hơn."},{"name":"Lời Chào Rơi Xuống Đất","tag":"Khó tạo lòng tin ban đầu.","story":"Bạn chuyển qua ba trại sơ tán trước năm mười tuổi, chưa kịp nhớ tên ai đã phải rời đi. Giờ bạn thường im lặng trước người lạ và bỏ lỡ những mối quen biết quý."}]}},"backstory":{"md":{"origin":["{name} lớn lên trên tầng thượng Chung cư Ánh Dương, nơi mẹ trồng rau trong những chiếc mũ bảo hiểm vỡ.","Trước dịch, {name} sửa thang máy ở {place}; {he} vẫn giữ một chiếc chìa khóa mở được tầng hầm đã bị niêm phong.","{name} từng bán cháo khuya trước Bệnh viện Hồng Phúc. {he} nhớ khẩu vị của cả những người đã chết.","{name} sinh ra cạnh Ga ngầm Bến Cũ, lớn lên bằng tiếng tàu và nghề móc ví khách ngủ gật.","Ngày trước, {name} lồng tiếng quảng cáo thuốc ho; bây giờ {he} chỉ nói nhỏ để khỏi đánh thức xác sống.","{name} từng kiểm kê hàng cho Chợ đêm Phố Đèn, giỏi nhìn thùng gỗ mà đoán đúng bên trong còn bao nhiêu đồ hộp.","{name} học hàn từ cha, dùng chiếc mặt nạ hình cá chép để vá cửa sắt cho {faction}.","Trước Hoại Huyết, {name} dạy bơi cho trẻ con trong một hồ cạn nước hai tháng mỗi năm.","{name} từng lái xe rác qua {place}; {he} thuộc mọi lối tắt có thể quay đầu một chiếc xe tải.","{name} lớn lên trong tiệm ảnh cưới. Chiếc máy in cũ vẫn nằm dưới giường, phủ kín bụi xi măng.","{name} từng làm người soát vé ở rạp chiếu phim; {he} giữ vé của buổi chiếu cuối cùng trong hộp diêm.","{name} học nghề điện lạnh ở {place}, quen ngủ cạnh tiếng máy nén nên đêm yên tĩnh lại thấy khó chịu."],"wound":["Trong đêm sơ tán khỏi {place}, {name} buông tay em trai để kéo sập cửa cuốn. Đến giờ {he} vẫn nghe tiếng đập cửa khi trời mưa.","{name} mất cả đội tiếp tế vì một chiếc radio phát sai tần số; {he} không tin bất kỳ lời chỉ đường nào qua loa.","Mẹ {name} chết trên giường bệnh còn nguyên dây truyền dịch. {he} giữ cái kẹp nhựa xanh như giữ một mảnh xương.","Một vết cắn giả khiến {name} bị đuổi khỏi {faction}; {he} mang vết sẹo do chính bạn cùng đội rạch để kiểm tra.","{name} từng khóa cửa tiệm để tránh đàn xác sống, không biết còn một đứa trẻ ngủ trong kho.","Chiếc xe cứu thương chở gia đình {name} hết xăng cách trạm trú đúng hai con phố. {he} từ đó luôn đổ đầy bình trước khi ngủ.","{name} sống sót sau vụ cháy ở {place}, nhưng mọi ảnh chụp trước dịch đều thành tro.","Cha {name} nhiễm bệnh giữa bữa tối. {he} vẫn không ăn món cá hộp hôm đó, dù đói đến run tay.","{name} bị bỏ lại trong thang máy mất điện ba ngày; {he} không bước vào chỗ kín nếu thiếu đèn pin.","Một chuyến đổi thuốc lấy pin thất bại khiến người yêu {name} không qua khỏi cơn sốt. {he} vẫn cất bốn viên pin chưa dùng.","{name} nhìn thấy {place} thất thủ qua ống nhòm, cách một con sông không có thuyền.","Hồi chuông báo động do {name} kéo quá sớm đã dẫn đàn xác sống đến cổng trại. {he} không còn đeo đồng hồ."],"motive":["{name} đi từ khu trú ẩn này sang khu khác để tìm một bác sĩ còn biết chữa nhiễm trùng máu.","{name} nhặt pin cho {faction}; {he} tin ánh đèn hành lang giúp người ta ngủ mà không cầm dao.","{name} theo dấu những xe phát thuốc cũ, hy vọng một thùng insulin còn nguyên đá lạnh.","{name} đổi bản đồ cống lấy thức ăn ở {place}; mỗi đường nét đều được kiểm lại bằng chính đôi giày rách.","{name} không ở đâu quá ba đêm, vì tiếng ho trong lúc ngủ dễ khiến cả phòng chĩa súng.","{name} gom chìa khóa nhà để trả cho người sống sót. {he} ghi địa chỉ lên từng mảnh băng dính.","{name} dẫn trẻ lạc về các trạm của {faction}, đổi công lấy một chỗ khô cho chúng ngủ.","{name} đi tìm nguồn điện cho chiếc tủ lạnh đựng vắc xin thử nghiệm đã bắt đầu ấm lên.","{name} sống bằng nghề sửa radio; {he} đổi một buổi bắt được tín hiệu lấy một bữa nóng.","{name} quay lại {place} mỗi tuần để thay nước cho mấy chậu cây trên mái.","{name} săn thuốc an thần, không phải để bán mà để giữ một bệnh nhân khỏi cắn đứt lưỡi.","{name} chuyển thư giữa các khu trú ẩn. {he} nói tin người nhà còn sống đáng giá hơn đạn."],"secret":["{name} giấu một người nhiễm Hoại Huyết trong phòng máy ở {place}; {he} đã ghi lại mười bảy ngày không có triệu chứng.","Tần số cứu hộ mà {name} nghe mỗi đêm là bản ghi cũ. {he} vẫn mở để người trong trại chịu ăn sáng.","{name} biết ai đã mở cổng {place} đêm thất thủ, vì chính bàn tay ấy đã đưa chìa khóa.","Trong đế giày {name} có sơ đồ kho thuốc của {faction}; {he} chưa dám giao vì trên đó đánh dấu một cửa bẫy.","{name} từng bán nước pha cồn sát khuẩn ở chợ đêm. {he} lén để lại tiền trước cửa những nhà đã mua.","Chiếc vòng trẻ con {name} đeo không phải kỷ vật gia đình; {he} lấy nó từ một xác sống mắc trong hàng rào.","{name} đã sửa một kết quả xét nghiệm thành âm tính để đưa một người bạn qua cổng kiểm dịch.","Mỗi tháng {name} nhận được một gói muối không đề tên ở {place}. {he} nhận ra nét buộc dây của người cha tưởng đã chết.","{name} thuộc mật khẩu cũ của kho súng {faction}, nhưng kho còn nhốt một người gác chưa được thả.","{name} giữ sổ ghi tên những người từng bị từ chối cứu hộ; dòng đầu tiên là chữ ký của {he}.","Đêm mất điện ở {place}, {name} nghe tiếng gõ từ buồng lạnh số sáu và đã gõ đáp lại.","{name} lén trồng thuốc phiện trên mái nhà để bào chế thuốc giảm đau; {he} sợ {faction} sẽ đốt cả vườn."],"hero":["Bạn tỉnh dậy trong kho giặt của {place}, tay ôm túi máu không cùng nhóm với mình.","Bạn từng ghi tên người mất tích cho {faction}; một hôm, tên của bạn xuất hiện trên tờ danh sách mới.","Bạn lớn lên dưới tiếng tàu ở Ga ngầm Bến Cũ, biết đường ray nào dẫn tới sân ga đã bị xây kín.","Bạn là người giao bình oxy cuối cùng cho Bệnh viện Hồng Phúc trước khi cổng bệnh viện hàn chết.","Bạn rời {place} với một xe đẩy trẻ em chứa toàn bộ dụng cụ sửa điện còn dùng được.","Bạn từng nấu ăn cho {faction}; sau một bữa tối thiếu đúng một suất, bạn bắt đầu học cách cầm súng.","Bạn tìm thấy ảnh mình trong ví một xác sống lạ, mặt sau ghi địa chỉ ở {place}.","Bạn sống qua mùa đông đầu tiên bằng cách đọc sách thành tiếng cho một phòng toàn giường trống.","Bạn từng dẫn đoàn sơ tán đi sai một ngã rẽ; con đường đúng vẫn được khoanh đỏ trên bản đồ bạn mang theo.","Bạn nhận ca gác ở {place} vì nơi đó còn điện, rồi phát hiện máy phát chỉ chạy từ nửa đêm đến ba giờ."],"look":["{name} buộc ba chiếc chuông xe đạp vào thắt lưng; {he} tháo chúng ra trước mỗi lần đi qua hẻm tối.","{name} có một vệt bỏng hình khóa kéo trên cổ tay. Khi nói dối, {he} lấy ngón cái miết dọc vệt sẹo.","{name} luôn mang hai đôi kính, một đôi không có tròng; {he} dùng nó khi muốn trông bớt mệt.","Tóc {name} bạc một mảng ngay trên tai trái; {he} nhuộm phần còn lại bằng mực bút lông.","{name} khâu túi áo bằng chỉ nha khoa, giấu trong đó một chiếc thìa inox cong.","Mỗi lần ngồi xuống, {name} xếp giày quay mũi ra cửa; {he} làm vậy cả lúc ăn cơm.","{name} đeo khẩu trang vá bằng vải rèm màu vàng; mắt {he} nhíu lại mỗi khi nghe tiếng còi xe.","Hai móng tay của {name} nhuộm tím thuốc sát khuẩn; {he} chà mãi vẫn không sạch.","{name} cài một chiếc vé tàu sau tai thay bút chì. Khi căng thẳng, {he} gấp nó nhỏ thêm một nếp.","{name} đi cà nhắc khi trời lạnh; {he} đếm bậc thang thành tiếng để giữ nhịp chân.","Cổ áo {name} lúc nào cũng cài lệch một nút. {he} bảo như vậy mới luồn tay lấy dao kịp.","{name} rửa chiếc cốc sứ mẻ quai sau mỗi bữa, kể cả khi {he} chỉ uống nước mưa."]},"tt":{"origin":["Ở {place}, {name} từng đúc chuông báo triều; mỗi chiếc chuông đều có một vết khía hình kiếm.","{name} lớn lên bên giếng thuốc của {faction}, quen phân biệt linh thảo bằng mùi nước đọng.","Thuở nhỏ tại {place}, {name} sống bằng nghề vá kiếm gãy, lấy linh sa giấu trong chuôi kiếm làm tiền công.","{name} từng chèo đò chở tu sĩ qua sương độc ở {place}; mái chèo cũ nay được mài thành kiếm gỗ.","Trước khi nhập đạo, {name} nuôi hạc đưa thư cho {faction}; có một con chỉ chịu bay vào đêm không trăng.","Nhà {name} ở sát lò luyện đan tại {place}; từ bé, tiếng nổ đan lô đã thay tiếng trống canh.","{name} từng khắc phù lên bia mộ vô danh ở {place}, mỗi tháng nhận công bằng một viên tụ khí đan.","Tại {place}, {name} làm nghề vớt kiếm dưới hồ; thanh đầu tiên vớt được vẫn còn nguyên hơi ấm.","{name} lớn lên trong đoàn buôn linh muối, thuộc đường qua {place} hơn cả thuộc kinh mạch bản thân.","Thuở chưa tu luyện, {name} canh vườn trúc của {faction}; đêm nào trúc cũng nghiêng về cùng một hướng.","{name} từng gõ mõ định giờ cho một đan phòng ở {place}; nhịp mõ cuối luôn chậm hơn nửa hơi thở.","Ở {place}, {name} học chữ từ những tờ kiếm phổ rách dùng để gói bánh."],"wound":["Một trận huyết vũ ở {place} cuốn mất sư phụ của {name}, chỉ để lại chiếc nhẫn còn đọng tro đỏ.","Trong lần thử đan của {faction}, kinh mạch {name} bị bỏng; từ đó linh khí vận hành nghe như tiếng cát chảy.","{name} từng cứu một đứa trẻ khỏi yêu thú ở {place}, đổi lại mất ba năm ký ức về kiếm pháp.","Đêm kết Trúc Cơ, {name} nghe tiếng chuông tang vọng ra từ đan điền; sáng hôm sau, cả nhà đã rời khỏi {place}.","Một thanh kiếm của {name} tự quay mũi trong lúc luận võ, để lại vết thương không khép trên lòng bàn tay.","Khi {place} bị phong sơn, {name} ở ngoài kết giới suốt bảy ngày, nhìn đèn nhà lần lượt tắt.","Một viên đan cứu mạng đã khiến {name} không còn nếm được vị ngọt; kẻ bán đan biến mất trước bình minh.","{name} đánh rơi ngọc bội hộ mệnh xuống Hồ Tẩy Kiếm; người lặn tìm thay đã không trở lên.","Trong trận hộ tống của {faction}, {name} nhận nhầm tín hiệu lửa, dẫn cả đội vào một cánh rừng không lối ra.","Lôi kiếp chưa tới mà tóc {name} đã bạc một lọn; cùng đêm ấy, tên trên gia phả hóa thành vết cháy.","Một lời thề lập ở {place} bị kẻ khác phá bỏ, nhưng phản phệ lại giáng xuống {name}.","{name} từng thấy bản mệnh kiếm của đồng môn vỡ thành bụi ngay trước cửa động phủ, từ đó không ngủ khi trời có sao."],"motive":["{name} đi khắp Thiên Nguyên để tìm loại mực có thể viết lên vỏ kiếm mà không bị linh khí xóa đi.","Mỗi mùa tuyết, {name} trở lại {place} đếm số tiếng chuông; năm nay đã thiếu một tiếng.","{name} nhận việc áp tiêu để lần theo dấu những kiện hàng niêm phong bằng sáp đen của {faction}.","{name} đổi đan dược lấy bản đồ giếng cổ, tin rằng dưới một giếng có lối vào kiếm mộ.","{name} săn yêu thú chỉ lấy răng nanh bên trái, dùng để trả một món nợ không ghi trong sổ.","Để luyện lại nhịp thở bị huyết kiếp làm loạn, {name} mỗi ngày phải đi đủ một nghìn bậc đá.","{name} lưu lại những quán trà ven đường, hỏi thăm một khúc kiếm ca chỉ còn người già nhớ được.","{name} muốn gom đủ chín mảnh gương đồng trước khi vầng huyết nguyệt kế tiếp xuất hiện.","Sau mỗi lần bán phù, {name} gửi một lá thư không đề tên về {place}; chưa lá nào được hồi âm.","{name} tìm những lò đan bỏ hoang, mong xác định nguồn gốc mùi thuốc vẫn hiện trong giấc ngủ.","{name} theo dấu đàn quạ trắng dọc Vạn Thú Sơn Mạch; nơi chúng đậu thường có linh mạch mới lộ.","{name} tiếp tục nhận nhiệm vụ của {faction} vì muốn tra lại một án phạt bị xóa khỏi ngọc giản."],"secret":["Khi đủ thân thiết, {name} sẽ thú nhận chiếc nhẫn tro đỏ thực ra mở được một cửa đá dưới {place}.","{name} giấu trong tay áo một lá bùa chưa vẽ xong; nét đầu tiên tự hiện lên mỗi khi huyết nguyệt tới.","Không ai biết {name} từng nghe tiếng gọi phát ra từ chính viên Kim Đan chưa kết thành.","{name} giữ một lọ nước ở {place}; trong lọ, bóng phản chiếu chậm hơn người soi đúng một nhịp.","Vết khía trên kiếm của {name} không phải dấu sửa chữa, mà là số lần một phong ấn dưới lòng đất rung chuyển.","{name} biết lối vào kho cũ của {faction}, bởi chìa khóa đã được khắc vào mặt trong một chiếc răng.","Mỗi lần dùng kiếm chiêu mạnh nhất, {name} mất đi ký ức về một khuôn mặt; danh sách ấy được chép trong giày.","{name} từng đổi tên một người đã chết trong sổ sinh tử của tà tu, rồi chôn cuốn sổ ở {place}.","Trong hộp thuốc của {name} có một hạt giống chỉ nảy mầm khi nghe lời nói dối.","{name} mang theo một mảnh ngọc giản ghi lời cảnh báo về huyết kiếp, nhưng nét chữ trùng với chữ của {name}.","{name} từng thả một yêu thú non khỏi trận pháp của {faction}; nay nó để vảy bạc trước cửa phòng mỗi năm.","Đêm mưa, {name} có thể nhìn thấy kiếm ý sót lại trên vết thương cũ; bí mật ấy chưa từng được ghi vào kiếm phổ."],"hero":["Bạn rời {place} với một thanh kiếm gỗ không lưỡi; đêm đầu tiên, chuôi kiếm mọc ra một chiếc lá bạc.","Bạn là đệ tử ghi sổ đan của {faction}, cho đến khi một phương thuốc thất truyền hiện ra bằng nét chữ của Bạn.","Bạn từng canh cổng núi tại {place}; sau một đêm huyết vũ, cánh cổng chỉ mở khi Bạn đặt tay lên đá.","Bạn sinh dưới tiếng chuông nứt ở {place}; mỗi khi vận khí, tiếng chuông ấy lại vang trong kinh mạch.","Bạn được {faction} nhặt về từ một chiếc thuyền trống, bên cạnh là chín viên linh thạch đã hóa đen.","Bạn học kiếm bằng cách chép bóng kiếm trên vách hang ở {place}; nét cuối cùng đến nay vẫn chưa chép nổi.","Bạn lớn lên trong tiệm bán phù rách; lá phù đầu tiên Bạn vẽ đã chỉ đường tới một động phủ bị niêm phong.","Bạn từng nuốt nhầm một viên đan vô danh tại {place}; từ đó có thể ngửi thấy linh khí trước cơn mưa.","Bạn giữ một mảnh lệnh bài của {faction}, dù sổ môn đồ không có tên Bạn và lệnh bài vẫn ấm như vừa rời lò.","Bạn xuống núi tìm nguồn cơn giấc mộng lặp lại: một hồ nước cạn, giữa lòng hồ cắm thanh kiếm mang ngày sinh của Bạn."],"look":["{name} buộc tóc bằng dây cung cũ; khi suy nghĩ, {he} vuốt đúng ba lần lên nút thắt.","Khóe mắt {name} có vệt son đỏ như chu sa; gặp ánh lửa, {he} thường kéo thấp vành nón.","{name} mặc áo tay trái dài hơn tay phải một đốt; lúc rút kiếm, {he} cuộn phần vải thừa quanh cổ tay.","Bên hông {name} treo túi hạt đào khô; đi được mười bước, {he} lại chạm túi một lần.","Móng út của {name} nhuộm màu linh mặc; khi đọc ngọc giản, {he} vô thức gõ móng lên mép bàn.","{name} có một lọn tóc bạc sát mang tai; trời nổi sấm, {he} lập tức dùng tay áo che lọn tóc ấy.","Giày của {name} luôn dính bụi trắng từ {place}; dù qua suối, {he} cũng không giũ sạch.","{name} đeo khuyên tai hình vảy cá bằng bạc; trước khi nói chuyện quan trọng, {he} xoay nó nửa vòng.","Trên cổ tay {name} có vết hằn tròn như miệng chén; uống trà nóng, {he} luôn đổi sang tay kia.","{name} thường ngậm một cọng cỏ linh đã khô; nghe tiếng kiếm rời vỏ, {he} cắn đứt cọng cỏ.","Áo choàng {name} khâu bằng chỉ xanh khác màu; khi ngồi, {he} luôn vuốt phẳng đúng đường chỉ ấy.","{name} mang theo chiếc lược sứ mẻ răng; mỗi sáng, {he} chải tóc trước khi lau kiếm."]},"sl":{"origin":["{name} lớn lên gần {place}, nơi đèn báo Cổng đỏ từng sáng suốt ba đêm.","Trước khi thức tỉnh, {name} sửa máy bán nước ở {place} và nhặt được một lõi ma thạch trong khay trả tiền.","{name} từng là người kiểm đếm xác quái cho {faction}; {he} nhận ra từng loài chỉ bằng mùi máu.","{name} sinh ra trong khu nhà tạm cạnh {place}, dưới mái tôn luôn rung mỗi khi Cổng mở.","Trước kia, {name} lái xe chở thương binh cho {faction}, thuộc mọi lối tắt dẫn tới {place}.","{name} từng trực tổng đài tại {place}; cuộc gọi đầu tiên từ trong Cổng không có số hiển thị.","{name} học làm bánh trước khi thức tỉnh; ổ bánh cuối cùng của {he} bị một con goblin cướp mất.","Thuở nhỏ, {name} bán pin dự phòng trước {place} cho thợ săn chờ vào Cổng.","{name} từng là kỹ thuật viên đo mana của {faction}, chuyên hiệu chuẩn máy bằng một chiếc nhẫn nứt.","{name} lớn lên trong nhà của một người canh Cổng; bữa tối luôn bắt đầu sau tiếng còi giải tán.","Trước khi cầm kiếm, {name} dọn vệ sinh ở {place} và tìm thấy dấu móng quái trên trần tầng hầm.","{name} từng vẽ bản đồ thoát hiểm cho {faction}; nét mực ở lối ra luôn đậm hơn các đường khác."],"wound":["Một Cổng hạng E vỡ ngay trước {place}; từ đó {name} không tin vào chữ “an toàn” trên bảng cảnh báo.","{name} mất người thân trong một cuộc đột kích của {faction}, nhưng hồ sơ ghi nguyên nhân là tai nạn giao thông.","Ngày thức tỉnh, {name} nghe tiếng chuông Hệ Thống giữa lễ tang và không kịp nhìn mặt người đã khuất.","Đồng đội của {name} biến mất sau cánh cửa trùm cuối; chỉ chiếc thẻ tên cháy sém được trả về.","{name} từng cứu một đứa trẻ khỏi Cổng, rồi phát hiện dấu răng quái trên vai đứa trẻ vào sáng hôm sau.","Một lần đo sai cấp Cổng khiến {name} bị tước giấy phép; vết xước trên máy đo vẫn còn nguyên.","Ở {place}, {name} chứng kiến bóng của người bạn đứng dậy trước cả thi thể.","{name} sống sót qua đợt tràn Cổng nhờ trốn trong tủ đông; tiếng máy nén giờ khiến {he} run tay.","Một thợ săn hấp hối đã trao {name} chiếc chìa khóa không mở được ổ nào ở {place}.","Sau trận đánh với quái hạng A, {name} quên sạch giọng nói của mẹ nhưng nhớ từng tiếng xương vỡ.","{faction} đóng hồ sơ vụ mất tích mà {name} theo đuổi; sáng đó, một trang hồ sơ xuất hiện dưới cửa phòng.","Lần đầu triệu hồi bóng tối, {name} nhận ra bóng ấy mang đôi giày của người vừa hy sinh."],"motive":["{name} đi qua {place} mỗi đêm, chờ chiếc máy bán vé in ra tấm vé ghi ngày mai.","{name} nhận mọi nhiệm vụ gần Cổng hạng thấp để tìm dấu hiệu của một con quái chưa từng được phân loại.","{name} cộng tác với {faction} vì kho lưu trữ của phe này giữ bản đồ các Cổng đã biến mất.","{name} không ở lâu một chỗ; cứ đúng nửa đêm, bóng của {he} lại chỉ về một hướng khác.","{name} dành tiền thưởng mua lại đồ thất lạc từ Cổng, đặc biệt là những chiếc đồng hồ đứng kim.","{name} tuần tra quanh {place} để kiểm tra vết nứt nhỏ trên bức tường phía đông.","{name} chỉ nhận đội hình có người mới, bởi một lời cảnh báo sớm từng cứu mạng {he}.","{name} săn quái hệ lửa để thu thập tro; trong tro thường hiện ra những ký tự Hệ Thống rất nhỏ.","{name} đổi bang hội liên tục, hy vọng tìm ra ai đã sửa báo cáo đột kích năm ấy.","{name} sống bằng việc vá giáp miễn phí cho thợ săn trở về từ Cổng một mình.","{name} mang theo máy ghi âm khi vào Cổng, quyết thu được tiếng nói vang lên sau lúc trùm bị hạ.","{name} tìm đến các điểm sơ tán cũ, nơi {he} tin vẫn còn người bị kẹt trong một tầng không gian."],"secret":["{name} giữ một thông báo Hệ Thống chưa hoàn thành: “Đừng để {place} thức tỉnh.”","{name} từng thấy biểu tượng của {faction} khắc trên ngực một con trùm không có tên.","Mỗi lần ngủ, {name} mơ thấy một binh đoàn bóng tối đứng im chờ {he} ra lệnh.","{name} có thể đọc chữ trên cổ vật Cổng, nhưng luôn giả vờ đoán nghĩa qua hình vẽ.","Chiếc điện thoại cũ của {name} vẫn nhận tin nhắn từ một đồng đội đã chết ba năm trước.","{name} từng xóa tên một người sống sót khỏi biên bản tràn Cổng theo lời cầu xin của chính người đó.","Dưới cổ tay {name} có ký hiệu chỉ hiện ra khi một Cổng hạng S chuẩn bị mở.","{name} biết lối vào bí mật ở {place}; cánh cửa ấy chỉ mở khi không có ai quan sát.","Một bóng binh lính luôn theo sau {name}, nhưng chưa từng nghe lệnh triệu hồi.","{name} cất lõi ma thạch còn đập như tim trong hộp cơm; mỗi tuần, lõi lại nặng thêm.","Tên của {name} xuất hiện trong danh sách tử vong của {faction} từ trước ngày {he} gia nhập.","{name} đã gặp một phiên bản khác của {he} trong Cổng, và người đó bảo đừng cứu trùm cuối."],"hero":["Bạn tỉnh dậy ở {place} với một cửa sổ Hệ Thống chỉ hiện hai chữ: “Đăng nhập.”","Bạn từng là thợ săn hạng E của {faction}; trong một Cổng bỏ hoang, bóng quái đầu tiên đã quỳ xuống.","Bạn lớn lên gần {place}, nơi tiếng còi báo Cổng từng thay chuông báo thức mỗi sáng.","Bạn sống sót sau cuộc đột kích mà toàn bộ hồ sơ bị xóa; Hệ Thống vẫn tính đó là nhiệm vụ đầu tiên.","Bạn nhận được nghề nghiệp ẩn trong lúc truyền máu ở {place}; túi máu bên cạnh lập tức hóa đen.","Bạn từng chuyển thư cho {faction}; một phong bì niêm kín ghi đúng ngày thức tỉnh của Bạn.","Bạn không nhớ mặt người đã kéo Bạn khỏi Cổng hạng S, chỉ nhớ bóng của người ấy không chạm đất.","Bạn bắt đầu săn quái để trả viện phí, rồi phát hiện mỗi lần lên cấp, một khoản nợ lại tự biến mất.","Bạn được Hệ Thống chọn khi đang chờ chuyến tàu cuối ở {place}; đồng hồ nhà ga khi ấy chạy ngược.","Bạn là người duy nhất bước ra khỏi một Cổng chưa từng được ghi nhận; trên tay là bản đồ của ngày mai."],"look":["{name} luôn đeo găng tay trái dù trời nóng; ngón út của {he} gõ nhịp mỗi khi Cổng rung.","{name} có một lọn tóc bạc sát thái dương; {he} thường vuốt nó trước khi nói dối.","{name} treo thẻ thợ săn ngược trên cổ áo; {he} bảo như vậy máy quét mana ít báo lỗi hơn.","{name} có vết sẹo hình dấu phẩy dưới mắt; {he} che nó bằng tóc khi gặp người của {faction}.","{name} luôn ngửi miệng cốc trước khi uống; {he} nói nước trong Cổng đôi khi có mùi sắt.","{name} buộc dây giày hai màu khác nhau; {he} thay bên trái sau mỗi lần thoát Cổng.","{name} mang đồng hồ hỏng trên cả hai cổ tay; {he} nhìn chiếc bên phải mỗi khi nghe tiếng chuông.","{name} có hình xăm mã Cổng sau gáy; {he} kéo cao cổ áo lúc đi ngang {place}.","{name} cất một chiếc thìa bạc trong túi áo; {he} xoay nó khi cần tập trung mana.","{name} bước rất khẽ dù đi giày bọc thép; {he} luôn dừng trước những góc tường tối.","{name} có đôi mắt đỏ vì thiếu ngủ; {he} đánh dấu lịch bằng những ngôi sao đen nhỏ.","{name} đội mũ bảo hộ cũ đầy vết cào; {he} chạm vào vết sâu nhất trước mỗi cuộc đột kích."]}},"relations":{"md":{"rel":{"friend":[["{hero}, anh mới tới {place} à? Đừng đứng sát cửa kính, ngoài đó có thứ thích nhìn vào.","Tôi là {npc}. Nếu anh cần nước sạch, hỏi tôi trước khi uống thứ trong bồn.","Anh nhặt được pin dự phòng thật à? Ở đây món đó quý hơn lời hứa đấy.","Cứ ngồi xuống đi, {hero}. Ghế chưa gãy, còn tôi thì chưa cắn ai."],["Tôi để phần cơm cho anh rồi. Đừng hỏi sao ít thịt, cả chợ đêm có ai thấy thịt đâu.","Đi tuần với anh đỡ chán hơn. Ít nhất anh biết lúc nào nên im lặng.","Hôm qua anh che lưng cho tôi. Tôi nhớ đấy, dù trí nhớ tôi tệ thật.","{hero}, mai qua Ga ngầm Bến Cũ với tôi nhé. Đi một mình nghe tiếng chân mình cũng phát sợ."],["Anh bị cắn ở đâu? Đưa tay đây, đừng giấu tôi như giấu tiền.","Cửa sắp bung rồi, {hero}. Tôi giữ chốt, anh đưa mọi người xuống hầm!","Tôi tưởng mất anh ở Bệnh viện Hồng Phúc. Lần sau muốn chết thì báo trước một tiếng.","Họ bảo bỏ anh lại cho kịp chuyến xe. Tôi bảo họ cứ lái, còn tôi ở đây."],["Anh về rồi. Tốt, tôi còn nợ anh một bữa ăn ra hồn.","Từ nay thấy tôi làm chuyện ngu, cứ kéo cổ áo lại. Bạn bè để làm việc đó mà.","Ngoài kia chẳng còn mấy thứ đáng giữ. Tình bạn này thì có, {hero}.","Nếu mai phải rời {place}, tôi đi cùng anh. Hai đứa mình lạc đường cũng quen rồi."]],"sworn":[["Tôi nghe anh đã cứu người ở {place}. Có gan đấy, nhưng gan không thay được áo giáp đâu.","{hero}, anh chia nửa bình nước cho người lạ thật à? Tôi muốn biết anh sống được bao lâu.","Đường này tôi rành, anh thì bắn khá. Đi chung một chuyến xem sao.","Đừng gọi tôi là anh em vội. Qua được đêm nay rồi nói."],["Từ giờ phần lưng tôi giao cho anh. Phần lưng anh, tôi trông.","Anh còn mạng thì tôi còn đường về. Nhớ thế mỗi khi định lao lên trước.","Tôi đã khâu vết thương cho anh; kim còn cắm trên áo đây. Đừng bắt tôi làm lại.","Người của {faction} hỏi chúng ta là gì. Tôi bảo: hai thằng khó chết."],["{hero}, thả tay tôi ra là anh thoát được. Nhưng đừng hòng bắt tôi cảm ơn.","Bọn Hoại Huyết tràn cầu thang rồi. Anh đưa dân ra ngoài, tôi chặn chúng.","Họ lấy anh để ép tôi mở cổng. Chúng chọn nhầm người để mặc cả rồi.","Anh đã cõng tôi qua ba tầng bệnh viện. Giờ đến lượt tôi kéo anh khỏi đây."],["Từ hôm nay, anh là anh em kết nghĩa của tôi. Sống thì cùng ăn, chết thì có người nhớ.","Chẳng cần chung máu, {hero}. Cùng giữ một cánh cửa qua đêm ấy là đủ.","Nhà tôi mất rồi, nhưng vẫn còn anh. Tôi không gọi đó là may mắn nhỏ.","Dù {place} có sập, tôi vẫn đứng bên anh. Lời này nói một lần là đủ."]],"sibling":[["{hero}? Đừng nhìn tôi như thế. Tôi cũng không tin mình tìm được anh ở đây.","Vết sẹo trên cổ tay anh... hồi nhỏ em làm đổ nước sôi, đúng không?","Anh còn giữ tấm ảnh ấy à? Em tưởng nó cháy cùng nhà rồi.","Nghe họ gọi tên anh, em cứ nghĩ mình nghe nhầm. Bao năm nay em toàn nghe nhầm."],["Anh ăn đi, em no rồi. Đừng có nhìn bát em, em nói thật được nửa câu đấy.","Em không còn là đứa bé anh phải dắt qua đường. Nhưng tối nay, cứ đi cạnh em.","Chị lại quên mang thuốc à, {hero}? Ngày xưa chị cũng quên áo mưa như thế.","Ở Chung cư Ánh Dương, em từng đứng chờ anh dưới cầu thang. Giờ thì thôi, em biết đi tìm."],["Anh mà bước qua cánh cửa đó một mình, em sẽ giận anh cả đời. Nếu còn cả đời.","Em đã mất anh một lần rồi. Lần này, kéo cả bệnh viện sập em cũng đưa anh ra.","Đừng bảo chị bỏ chạy. Người nhà mình đã bỏ lại quá nhiều người rồi.","Họ nói anh nhiễm Hoại Huyết. Em cần kết quả xét nghiệm, không cần lời đồn."],["Bữa nay em nấu cháo khét. Anh ăn đi, đúng vị nhà mình ngày trước.","Chúng ta không lấy lại được những năm đã mất. Nhưng sáng mai, em sẽ ở đây.","Anh cứ đi làm việc của anh. Tối về nhớ gõ cửa ba tiếng, em mở.","Em từng nghĩ mình là người cuối cùng của nhà này. Cảm ơn anh vì đã chứng minh em sai."]],"lover":[["{hero}, áo anh dính bụi rồi. Xin lỗi, tôi chỉ định phủi giúp thôi.","Tôi giữ chỗ cạnh đèn cho anh. Ở đây tối quá, ngồi gần nhau đỡ lạnh.","Anh hay trực ca khuya à? Vậy chắc chúng ta còn gặp nhau nhiều.","Hôm nay anh cười ở Chợ đêm Phố Đèn. Tôi quên mất mình đang định mua gì."],["Tôi pha trà cho anh, hơi nhạt. Tay tôi run, nhưng không phải vì lạnh.","Mỗi lần cổng mở, tôi lại ngước nhìn. Tôi biết mình đang chờ ai rồi.","Anh đừng liều chỉ để tỏ ra mạnh mẽ. Tôi thích anh nguyên vẹn hơn.","Nếu anh rảnh sau ca gác, mình đi dọc sân thượng nhé. Trăng vẫn còn đó."],["Họ báo anh mắc kẹt trong ga. Tôi biết đường vào; anh đợi tôi.","Tôi sợ lắm, {hero}. Sợ đến mức không thể đứng yên khi anh còn ở ngoài kia.","Đừng hứa sẽ không sao. Cứ nắm tay tôi và bước tiếp.","Nếu chuyến xe chỉ còn một chỗ, anh lên đi. Tôi sẽ tìm đường tới anh."],["Ngày mai chưa chắc yên, nhưng tối nay tôi muốn ở bên anh.","Tôi yêu anh, {hero}. Giữa đống đổ nát này, điều đó vẫn thật rõ ràng.","Khi mọi chuyện qua đi, mình trồng một chậu cây nhé. Anh nhớ tưới, tôi hay quên.","Cứ về với tôi sau mỗi chuyến đi. Tôi sẽ luôn chừa một ngọn đèn."]],"rival":[["{hero}, nghe nói anh bắn giỏi. Bia ở cuối sân kia chưa nghe nói thế.","Đừng giành chuyến hàng này với tôi. Hay cứ thử, xem ai mang được nó về trước.","Anh là người mới của {faction} à? Để xem họ khen anh quá lời không.","Tôi không nhường đường vì anh đến trước. Ở đây ai giữ được cửa thì người đó đi."],["Anh lại nhanh hơn tôi một bước. Khó chịu thật, nhưng đường anh chọn không tệ.","Đừng tưởng cứu tôi một lần là thắng. Lần sau tôi tự thoát được.","Tôi đã tập bắn cả đêm. Mai anh đừng viện cớ súng kẹt.","Anh làm tốt vụ Bến Cũ. Tôi ghét phải nói câu này, nên nghe cho kỹ."],["Cùng một thùng thuốc, hai đội đang chờ. {hero}, hôm nay chúng ta phải phân thắng bại.","Tôi không để anh nhận hết lỗi vụ sập cổng. Tôi cũng đứng ở đó.","Anh bị thương mà còn đòi đấu? Thắng kiểu ấy tôi chẳng khoe với ai được.","Đám xác sống kéo tới rồi. Gác chuyện thắng thua lại, giữ cửa trước đã."],["Anh thắng. Giờ cất cái mặt đắc ý đi và giúp tôi chuyển thuốc.","Hòa nhé, {hero}. Lần đầu tôi thấy thua một nửa cũng vui.","Tôi vẫn muốn vượt anh. Nhưng từ giờ, cần người canh lưng thì cứ gọi.","Hôm nay tôi thắng; mai có thể là anh. Miễn cả hai còn sống để đấu tiếp."]],"enemy":[["{hero}, cuối cùng cũng thấy mặt anh. Người nhà tôi chết ở {place}, còn anh bước ra được.","Anh mang phù hiệu {faction} à? Tôi đã tìm người đeo nó lâu lắm rồi.","Đứng lại. Tôi muốn nghe anh giải thích vì sao cổng đóng khi chúng tôi còn ở ngoài.","Anh không nhớ tôi đâu. Tôi thì nhớ giọng anh qua chiếc bộ đàm hôm ấy."],["Tôi tìm thấy dấu giày anh ở Ga ngầm Bến Cũ. Đừng phí sức xóa nữa.","Anh trốn sau tường của Liên Minh Khu Trú Ẩn được bao lâu, {hero}?","Tôi đã chặn lối ra phía đông. Lần này anh phải nói chuyện với tôi.","Người của anh đã thấy tôi ở Chợ đêm Phố Đèn. Tốt, bảo họ rằng tôi vẫn đang tìm anh."],["Đặt súng xuống, {hero}. Hôm nay không còn cánh cửa nào để anh khóa lại.","Anh bảo đó là lệnh sơ tán. Em tôi gọi nó là đêm bị bỏ rơi.","Tôi đã chờ cuộc đối mặt này quá lâu. Đừng bắt tôi nghe thêm một lời nói dối.","Nhìn thẳng vào tôi. Nếu anh không ra lệnh đóng cổng, hãy nói ai đã làm."],["Tôi đã đọc sổ trực. Anh cố mở cổng, còn tôi săn đuổi nhầm người.","Anh tha tôi, nhưng món nợ máu vẫn còn. Tôi sẽ tìm kẻ thật sự ra lệnh.","Xong rồi, {hero}. Tôi đã báo thù; giờ chẳng còn ai để đổ lỗi cho nỗi đau này.","Anh thắng. Tôi không xin anh quên chuyện cũ, chỉ xin một cơ hội sửa điều mình gây ra."]],"mentor":[["{hero}, cầm dao như thế chỉ tổ rách tay. Lại đây, tôi chỉ anh cách giữ.","Ở Bệnh viện Hồng Phúc, nghe tiếng dép kéo lê thì đừng gọi tên người ta.","Trước khi mở cửa, nhìn khe dưới. Máu chảy vào phòng thường đến trước con vật.","Anh muốn theo đội cứu hộ? Được, nhưng học cách băng bó trước cách bắn."],["Khá hơn rồi. Hôm nay anh nhớ kiểm tra lối thoát trước khi lao vào.","Đừng xấu hổ vì sợ, {hero}. Sợ giúp tay anh tránh được nút cò lúc có người đi ngang.","Tôi giao anh dẫn đường một chuyến. Lạc thì cùng tìm, đừng tự mình liều.","Anh đã biết cứu một người. Giờ học cách đếm xem phía sau còn mấy người."],["Tôi bị kẹt chân, anh dẫn họ đi. Nhớ đường ống kỹ thuật tôi đã chỉ.","Hết đạn rồi thì dùng đầu óc, {hero}. Cái van đỏ ngay sau lưng anh.","Anh phải chọn cứu người đang thở trước. Đau thì cứ để lát nữa đau.","Hôm nay tôi không ra lệnh nữa. Nói tôi nghe anh định đưa cả đội qua đó thế nào."],["Anh không cần tôi cầm tay chỉ đường nữa. Tôi mừng, dù hơi buồn.","Tôi dạy anh cách sống sót; cách giữ lòng mình, anh tự học còn giỏi hơn.","Từ mai anh huấn luyện người mới đi. Tôi sẽ ngồi gần đó và cố không xen vào.","Khi anh không biết chọn gì, hãy nhìn những người anh đưa về được. Họ là câu trả lời."]]},"links":{"sibling":["{a} và {b} là anh em ruột, tìm lại nhau sau đợt sơ tán ở Bến Cũ.","{a} là chị của {b}; cả hai nhận ra nhau nhờ tấm ảnh nhàu trong túi áo.","{a} và {b} cùng lớn lên ở Chung cư Ánh Dương, rồi thất lạc khi virus lan tới.","{a} luôn để dành phần ăn cho {b}, dù hai anh em còn hay cãi nhau."],"ex":["{a} và {b} từng yêu nhau, nhưng chia tay sau một chuyến cứu hộ không ai muốn nhắc.","{a} vẫn giữ chiếc bật lửa {b} để lại từ ngày hai người đường ai nấy đi.","{a} và {b} là người cũ; gặp nhau ở chợ đêm, họ chỉ hỏi thăm chuyện ăn ngủ.","{a} từng chờ {b} ở Ga ngầm Bến Cũ quá lâu, rồi học cách sống tiếp."],"rival":["{a} và {b} thường tranh quyền dẫn đội, nhưng chưa từng bỏ mặc nhau.","{a} xem {b} là đối thủ bắn súng đáng gờm nhất khu trú ẩn.","{a} và {b} đua nhau mang thuốc về từ vùng nhiễm, lần nào cũng sát nút.","{a} không thích cách {b} làm việc, song luôn kiểm tra xem người kia đã về chưa."],"mentor":["{a} dạy {b} cách tìm lối thoát trong những tòa nhà mất điện.","{a} từng là bác sĩ ở Hồng Phúc và chỉ {b} cách khâu vết thương.","{a} là người hướng dẫn {b} trong chuyến cứu hộ đầu tiên.","{a} dạy {b} kiểm tra tiếng động trước khi mở cửa, một thói quen đã cứu nhiều mạng."],"debt":["{a} nợ {b} một mạng từ đêm ga ngầm bị tràn xác sống.","{a} chưa quên việc {b} chia viên thuốc cuối cùng cho mình.","{a} nợ ơn {b}, người đã đưa mẹ của {a} ra khỏi Bệnh viện Hồng Phúc.","{a} giúp {b} sửa máy phát mỗi khi nó hỏng, coi như trả dần món nợ cũ."],"lover":["{a} và {b} yêu nhau, thay phiên trực đêm để người kia được ngủ.","{a} luôn chừa một chỗ cạnh bếp sưởi cho {b}.","{a} và {b} tìm thấy nhau ở Chợ đêm Phố Đèn, rồi không muốn lạc nhau nữa.","{a} và {b} hẹn trồng một cái cây khi tìm được nơi ở lâu dài."],"enemy":["{a} hận {b} vì tin rằng {b} đã khóa cổng khi gia đình mình còn ở ngoài.","{a} săn đuổi {b} từ sau vụ cháy kho thuốc ở Hồng Phúc.","{a} không tha thứ cho {b} về những người đã chết trong chuyến sơ tán.","{a} giữ chiếc bộ đàm hỏng làm lời nhắc rằng mình còn món nợ máu với {b}."]},"gift":{"like":["Cho tôi thật à, {hero}? Tôi đã tìm thứ này suốt mấy tuần.","Đúng món tôi cần. Tối nay tôi có thể ngủ mà không lo máy phát tắt.","Anh nhớ tôi thích thứ này sao? Cảm ơn, tôi sẽ giữ kỹ.","Tốt quá. Tôi chia một ít cho mấy đứa nhỏ ở {place} được không?","Trời, còn dùng được này. Anh làm tôi vui hơn cả lúc thấy thùng đồ hộp.","Cảm ơn anh. Mai cần tôi giúp gì, cứ gọi thẳng tên."],"dislike":["Tôi nhận nhé, nhưng lần sau đừng nhặt thứ này cho tôi.","Cảm ơn anh. Tiếc là tôi không dùng được nó.","Anh lấy nó từ đâu ra vậy? Thôi, đừng kể.","Ừm... để tôi xem có ai ở {place} cần món này không.","Ý anh tốt, tôi biết. Nhưng thứ này làm tôi nhớ chuyện không vui.","Tôi nhận vì anh đã mang tới. Lần sau hỏi tôi trước nhé."]},"join":["Tôi đi cùng anh, {hero}. Chờ tôi lấy túi cứu thương.","Được, ra khỏi {place} thôi. Anh đi trước, tôi khóa cửa.","Cho tôi hai phút kiểm tra đạn. Tôi không muốn giữa đường mới biết mình hết.","Tôi theo anh. Nhưng thấy người bị nạn thì mình dừng lại giúp.","Đi chứ. Ở đây ngồi nghe máy phát ho mãi cũng phát điên.","Tôi sẵn sàng rồi. Anh chọn đường, tôi để mắt hai bên."],"leave":["Được, tôi ở căn cứ. Anh nhớ báo về trước khi trời tối.","Tôi sẽ canh cổng. Có chuyện gì, gọi qua bộ đàm ngay.","Ừ, chuyến này tôi ở lại. Đừng biến nó thành chuyến cuối của anh.","Tôi hiểu. Tôi lo thuốc men ở đây, anh lo đường về."],"duel":["{hero}, sân đã dọn trống. Xem hôm nay ai phải đãi bữa tối.","Đừng nương tay. Tôi muốn biết mình đã tiến bộ đến đâu.","Sẵn sàng chưa? Lần này tôi không để anh cướp thế trước đâu.","Chúng ta đấu một trận cho rõ. Xong rồi cùng đi sửa cái cổng chết tiệt ấy."],"ambush":["{hero}! Tôi đã đợi anh qua con hẻm này.","Đừng chạy về phía chợ. Người của tôi đang chặn lối đó.","Anh nghe tiếng lon lăn không? Bẫy đấy, và giờ thì muộn rồi.","Bỏ súng xuống! Lần này tôi không đến để nghe anh xin lỗi."],"mercy":["Sao anh không kết liễu tôi? Sau từng ấy chuyện, tôi không hiểu nổi.","Tôi thua rồi. Anh tha mạng thì tôi sẽ nói hết những gì mình biết.","Đừng đưa tay đỡ tôi vội. Tôi cần một phút để tin anh thật sự tha cho mình.","Tôi đã săn anh khắp thành phố. Giờ anh cho tôi sống; món nợ này tôi sẽ tự gánh."],"confess":["{hero}, tôi yêu anh. Tôi đã muốn nói từ những đêm cùng anh canh cổng.","Tôi cứ mong anh trở về, rồi nhận ra điều mình mong là được ở bên anh.","Nếu anh cũng có tình cảm với tôi, tối mai mình lại gặp nhau dưới ngọn đèn ấy nhé.","Tôi thương anh, {hero}. Tôi muốn nói rõ, để ngày mai có ra sao anh cũng biết."],"oath":["{hero}, từ nay anh là anh em kết nghĩa của tôi. Có đường sống, ta cùng tìm.","Tôi thề không bỏ anh lại giữa đường. Anh cũng phải giữ mạng mà về.","Không chung máu mủ, nhưng từ đêm nay chúng ta là người nhà.","Tôi lấy mạng mình giữ lời: anh gặp nạn, tôi sẽ đến."]},"tt":{"rel":{"friend":[["{hero}, lần đầu gặp ở {place}, ta đã thấy kiếm ý của ngươi bất phàm.","Đạo hữu cũng đến tìm linh thảo? Vậy chúng ta đi chung một đoạn.","Ta là {npc}. Nếu ngươi chưa quen đường núi, cứ theo ta.","Kiếm của ngươi tốt đấy, {hero}. Có dịp cùng ta luận kiếm."],["{hero}, có ngươi đồng hành, đường qua Vạn Thú Sơn Mạch bớt phần hiểm trở.","Ta để dành cho ngươi một viên Tụ Khí Đan. Đừng khách sáo.","Chuyện ngươi giấu trong lòng, nếu muốn kể, ta sẽ nghe.","Hôm nay ta lĩnh thưởng ở {faction}; tối nay mời ngươi một vò rượu."],["{hero}, lui lại! Yêu thú này để ta cản.","Ngươi từng cứu ta giữa huyết kiếp. Lần này, đến lượt ta.","Nếu phải chọn giữa cơ duyên và tính mạng ngươi, ta chẳng cần nghĩ.","Đừng ngủ, {hero}. Ta đã mang đan dược tới rồi!"],["Sau bao phen sinh tử, ngươi vẫn là người ta tin nhất.","Mai này mỗi người một ngả, cứ gửi truyền âm phù; ta sẽ đến.","Có ngươi cùng ngắm mây trên Thanh Vân Sơn, đời tu tiên cũng không quá lạnh.","Cửa động phủ của ta luôn mở cho ngươi, {hero}."]],"sworn":[["{hero}, ngươi có dám cùng ta uống cạn vò rượu này không?","Ta là {npc}. Kiếm của ngươi khiến ta muốn kết giao.","Cùng thoát khỏi trận pháp ấy, xem ra chúng ta có chút duyên.","Ngươi trọng nghĩa khí. Ta kính ngươi một chén."],["{hero}, nếu ngươi không chê, từ nay gọi ta một tiếng đệ.","Huynh có nạn, truyền âm cho đệ; cách nghìn dặm đệ cũng tới.","Chén rượu kết nghĩa hôm ấy, đệ chưa từng quên.","Đệ nhặt được linh thạch này. Huynh giữ lấy để trúc cơ."],["Huynh đi trước đi! Đệ sẽ giữ cửa trận đến cùng.","Kẻ nào muốn lấy mạng huynh, phải bước qua kiếm của đệ.","Dù kim đan vỡ nát, đệ cũng không bỏ huynh một mình.","Huynh còn nhớ lời thề dưới Hồ Tẩy Kiếm không? Hôm nay đệ đến giữ lời."],["Kiếp nạn đã qua. Đệ mừng vì còn được gọi huynh một tiếng.","Từ Thanh Vân Sơn đến tận chân trời, đường của huynh cũng là đường của đệ.","Ngày huynh lập tông, nhớ chừa cho đệ một chỗ uống rượu.","Chúng ta chẳng cùng huyết mạch, nhưng nghĩa huynh đệ này cả đời không đổi."]],"sibling":[["{hero}, ngọc bội của huynh... sao lại giống chiếc mẫu thân để lại cho đệ?","Đệ là {npc}. Nghe huynh kể quê cũ, lòng đệ bỗng thấy thân quen.","Huynh cũng biết khúc đồng dao ấy ư? Đệ tưởng chẳng còn ai nhớ.","Vết sẹo trên tay huynh... hồi nhỏ, có phải đệ đã gây ra?"],["Mẫu thân tìm huynh suốt bao năm. Đệ chẳng ngờ hôm nay lại gặp huynh ở {place}.","Huynh đừng nhường hết đan dược cho đệ; huynh cũng cần dưỡng thương.","Thuở nhỏ đệ cứ mong có huynh che chở. Nay huynh thật sự ở đây rồi.","Đệ đã khâu lại túi càn khôn cho huynh. Đừng đánh rơi nữa."],["Huynh là người thân cuối cùng của đệ. Đừng bước vào huyết trận!","Năm ấy đệ lạc mất huynh một lần; hôm nay quyết không buông tay.","Đệ đã giữ di vật của phụ thân. Huynh phải sống để tự tay nhận lấy.","Huynh bị thương rồi! Đừng nói không sao, đệ nhìn ra mà."],["Nhà cũ chẳng còn, nhưng nơi nào có huynh, nơi ấy là nhà của đệ.","Đợi huyết kiếp lắng xuống, huynh cùng đệ về thắp hương cho mẫu thân nhé.","Huynh cứ đi theo tiên đạo. Đệ sẽ giữ ngọn đèn chờ ngày huynh trở lại.","Từ nay chúng ta không còn phải tìm nhau giữa biển người nữa."]],"lover":[["{hero}, gặp ngươi bên Hồ Tẩy Kiếm, ta nhất thời quên cả phép chào.","Ta là {npc}. Trời lạnh thế này, ngươi có muốn cùng ta uống trà không?","Kiếm tu các ngươi đều ít lời như vậy, hay chỉ riêng ngươi?","Vừa rồi ngươi nhìn sang, ta suýt đánh rơi ngọc giản."],["Hôm nay thấy ngươi bình an trở về, lòng ta mới yên.","Ta luyện chiếc hộ phù này cho ngươi; đường xa nhớ mang theo.","Ngươi vừa gọi tên ta ư? Xin lỗi, ta còn muốn nghe thêm một lần.","Ở cạnh ngươi, đến lúc tĩnh tọa ta cũng khó giữ tâm như chỉ thủy."],["Nếu huyết kiếp cuốn ngươi đi, ta sẽ tìm đến tận cuối Thiên Nguyên đại lục.","Đừng lấy thân chắn kiếm cho ta nữa. Ta sợ mất ngươi.","Ta có một lời cất giữ đã lâu; qua được đêm nay, xin hãy nghe.","Ngươi nắm tay ta đi. Trận này, chúng ta cùng vượt."],["Ta thương ngươi, {hero}. Từ nay chẳng muốn giấu nữa.","Dẫu tiên lộ dài hơn ngàn năm, ta vẫn muốn đi bên ngươi.","Đợi hoa trên Thanh Vân Sơn nở, ta cùng ngươi về ngắm nhé.","Lời ước dưới trăng hôm ấy, ta sẽ giữ đến khi tóc bạc."]],"rival":[["{hero}, nghe nói kiếm pháp ngươi đứng đầu lứa này. Ta muốn thử.","Ta là {npc}. Đừng để ta thất vọng ở kỳ đại hội tới.","Cùng tranh một suất vào Tàng Kiếm Các ư? Vậy gặp nhau trên lôi đài.","Kiếm chiêu vừa rồi khá lắm, nhưng ngươi còn sơ hở."],["Ngươi lại nhanh hơn ta một bước. Lần sau sẽ không thế đâu.","Viên Trúc Cơ Đan ấy, ta sẽ tự tay giành lấy.","Đừng tưởng ta chỉ biết ganh đua; kiếm ý của ngươi, ta thật lòng khâm phục.","Ngươi tiến cảnh nhanh như vậy, ta càng không thể lười biếng."],["Hôm nay không còn đường lui. Rút kiếm đi, {hero}!","Ta đợi trận này quá lâu rồi; hãy cho ta thấy toàn bộ bản lĩnh của ngươi.","Nếu ngươi ngã xuống ở đây, ta sẽ chẳng bao giờ cam lòng.","Một kiếm định thắng bại. Ngươi dám chứ?"],["Trận này ta thua. Lần tới, ta sẽ thắng cho ngươi xem.","Ngươi thắng rồi, {hero}. Từ nay ta kính ngươi như một đạo hữu.","Chúng ta đã phân cao thấp; giờ cùng uống một chén được chứ?","Kiếm đạo còn dài. Có ngươi làm đối thủ, ta chẳng sợ đường xa."]],"enemy":[["{hero}, chính ngươi là kẻ được {faction} che chở? Ta muốn xem họ cứu ngươi thế nào.","Nợ máu ở Trấn Lạc Hà, ta sẽ tính lên đầu ngươi.","Ngươi mang thanh kiếm ấy ư? Ta nhận ra nó, dù vỏ kiếm đã đổi.","Ta là {npc}. Nhớ lấy tên kẻ sẽ đòi món nợ cũ."],["Cứ chạy đi, {hero}. Dấu linh lực của ngươi chưa thoát khỏi tay ta.","Ngươi trốn vào Thanh Vân Sơn cũng vô ích; ta sẽ tìm tới.","Đồng bọn ngươi cản được ta một lần, không cản được lần thứ hai.","Mỗi ngày ngươi còn sống, mối hận này càng nung nóng kiếm của ta."],["Đêm nay, giữa {place}, ta và ngươi phải chấm dứt ân oán.","Rút kiếm! Ta không đến đây để nghe ngươi biện bạch.","Ngươi còn nhớ những người đã chết ở Trấn Lạc Hà không?","Ta đã bỏ cả kim đan để đổi lấy trận pháp này. Ngươi đừng mong thoát."],["Ngươi tha ta, nhưng mối hận này chưa thể tan trong một ngày. Ta sẽ rời đi.","Chân tướng đã rõ. Ta hận lầm ngươi; món nợ này, ta sẽ trả.","Ta đã báo thù xong. Vậy mà lòng vẫn trống rỗng.","Kiếm của ta gãy rồi. Từ nay ân oán giữa chúng ta cũng dừng tại đây."]],"mentor":[["{hero}, căn cơ ngươi chưa vững; khoan vội dẫn linh khí vào kinh mạch.","Ta là {npc}. Nếu muốn học kiếm, trước hết hãy học đứng cho vững.","Tư chất khá, nhưng tâm quá gấp. Ngươi tên gì?","Đến Hồ Tẩy Kiếm lúc bình minh; ta sẽ xem ngươi có chịu được khổ không."],["Hôm nay ngươi giữ được kiếm tâm giữa loạn trận. Ta rất hài lòng.","Viên đan này giúp ngươi dưỡng mạch; đừng dùng nó để ép phá cảnh.","Ngươi chưa hiểu thức kiếm cuối, vì ngươi vẫn sợ thất bại.","Ta chỉ đường, còn từng bước trúc cơ phải do chính ngươi đi."],["Kim đan kiếp sắp giáng. Bình tâm, nhớ nhịp thổ nạp ta đã dạy.","Ta không thể thay ngươi gánh lôi kiếp, nhưng sẽ giữ hộ pháp đến phút cuối.","Giữa sống chết, đừng cầu kiếm nhanh; hãy nhìn cho rõ một đường kiếm.","Nếu trận này ta không trở về, ngọc giản trong tay áo là dành cho ngươi."],["Ngươi đã vượt xa điều ta từng mong. Từ nay, hãy tin vào đạo của mình.","Sư đồ một trận, thấy ngươi thành tài, ta không còn gì tiếc nuối.","Đường phía trước ta chẳng dạy được nữa; lúc nào mỏi mệt, cứ về tìm ta.","Kiếm của ngươi đã có tiếng nói riêng. Hãy mang nó đi khắp Thiên Nguyên."]]},"links":{"sibling":["{a} và {b} là huynh muội thất lạc từ nhỏ, nhận nhau nhờ đôi ngọc bội.","{a} là huynh trưởng của {b}, từng thay em gánh phạt ở Thanh Vân Tông.","{a} và {b} cùng huyết mạch, nhưng lớn lên ở hai tông môn đối địch.","{a} là tỷ tỷ của {b}; mỗi năm đều gửi đan dược về cho em."],"ex":["{a} và {b} từng hẹn ước bên Hồ Tẩy Kiếm, rồi chia tay vì khác tiên đạo.","{a} từng là đạo lữ của {b}; một lần bế quan đã khiến họ xa nhau.","{a} và {b} đã cắt đứt tình duyên, song vẫn giữ tín vật của nhau.","{a} từng chờ {b} trở về Trấn Lạc Hà, cho đến khi lời hẹn cũ phai đi."],"rival":["{a} và {b} tranh vị trí đứng đầu kiếm bảng suốt ba năm.","{a} xem {b} là đối thủ duy nhất đủ sức tiếp trọn ba kiếm của mình.","{a} và {b} cùng tìm một truyền thừa trong Vạn Thú Sơn Mạch.","{a} chưa từng thắng {b} trên lôi đài, nhưng lần nào cũng trở lại."],"mentor":["{a} truyền cho {b} thức kiếm đầu tiên dưới chân Thanh Vân Sơn.","{a} là sư phụ của {b}, nghiêm khắc canh giữ từng bước trúc cơ.","{a} dẫn {b} nhập đạo, rồi giao lại một quyển kiếm phổ cũ.","{a} dạy {b} luyện đan ở Dược Vương Cốc, trước hết là cách nhận độc thảo."],"debt":["{a} nợ {b} ơn cứu mạng sau trận thú triều.","{a} nợ {b} một viên Hồi Mệnh Đan và lời hứa sẽ trả khi cần.","{a} nợ {b} ơn che chở gia quyến trong huyết kiếp.","{a} nợ {b} cơ hội trúc cơ, bởi năm ấy {b} đã nhường phần linh tuyền."],"lover":["{a} và {b} là đạo lữ, cùng tu luyện trên Thanh Vân Sơn.","{a} và {b} trao tín vật bên Hồ Tẩy Kiếm, hẹn cùng vượt kim đan kiếp.","{a} và {b} yêu nhau, dù mỗi người phụng sự một tông môn.","{a} và {b} thường hẹn gặp dưới đèn hoa ở Trấn Lạc Hà."],"enemy":["{a} hận {b} vì cho rằng {b} đã hại sư phụ mình.","{a} truy tìm {b} để đòi món nợ máu ở Trấn Lạc Hà.","{a} hận {b} sau lần tranh đoạt truyền thừa khiến đồng môn bỏ mạng.","{a} thề báo thù {b}, kẻ đã phá hủy động phủ của mình."]},"gift":{"like":["Ngươi còn nhớ ta thích thứ này ư? Ta sẽ giữ cẩn thận.","Linh thảo này đúng lúc ta cần. Đa tạ, {hero}.","Món quà đẹp quá; ta nhìn mãi mà chẳng nỡ cất đi.","Ngươi tặng ta kiếm tuệ này sao? Để ta buộc lên chuôi kiếm.","Đan hương thật dịu. Tấm lòng của ngươi, ta xin nhận.","Ta chỉ nhắc một lần mà ngươi đã nhớ. Đa tạ ngươi."],"dislike":["Ta biết ngươi có lòng, nhưng thứ này không hợp với ta.","Mùi linh thảo này làm ta nhức đầu. Ngươi giữ lại nhé.","Kiếm tuệ này đẹp, chỉ tiếc kiếm của ta không dùng được.","Ta xin nhận tấm lòng; món quà này, ngươi hãy tặng người cần hơn.","Lần sau đừng tốn linh thạch vì ta vào thứ này.","Ngươi không biết ta kiêng loại đan dược ấy ư? Thôi, không sao."]},"join":["Ta đi cùng ngươi, {hero}. Đường qua {place} không dễ vượt một mình.","Được, ta thu xếp xong sẽ lên đường cùng ngươi.","Ngươi cần một người hộ pháp? Ta nhận lời.","Thanh kiếm này còn dùng được. Dẫn đường đi, {hero}.","Ta đã chờ ngươi mở lời từ lâu; lần này cùng đi.","Vì chuyện ở {place}, ta cũng phải đến đó. Chúng ta đồng hành."],"leave":["Ta sẽ ở lại trông coi động phủ. Ngươi nhớ truyền âm báo bình an.","Được, ta ở lại căn cứ; có biến, cứ gửi tín phù.","Ta không theo nữa, nhưng sẽ giữ sẵn đan dược đợi ngươi về.","Ngươi cứ đi. Phòng tuyến nơi này giao cho ta."],"duel":["{hero}, lên lôi đài! Hôm nay ta muốn thử kiếm mới của ngươi.","Ba chiêu đầu ta sẽ không nhường. Rút kiếm đi!","Trận trước ngươi thắng; trận này xem ai tiến bộ hơn.","Đừng giữ sức, {hero}. Ta muốn thua dưới toàn lực của ngươi."],"ambush":["{hero}, ngươi bước vào trận rồi. Hôm nay không ai cứu được ngươi!","Động thủ! Đừng để {hero} thoát khỏi sơn cốc!","Ta đã đợi ngươi ba ngày ở đây. Nợ cũ, trả đi!","Kiếm trận khép lại! {hero}, ngươi còn đường nào để chạy?"],"mercy":["Vì sao ngươi tha ta? Ta từng muốn lấy mạng ngươi.","Ta bại rồi. Ân không giết này, ta sẽ ghi nhớ.","Thu kiếm đi... Ta sẽ không đuổi theo ngươi nữa.","Ngươi có thể giết ta, nhưng đã không làm. Ta cần thời gian nghĩ cho rõ."],"confess":["{hero}, ta thương ngươi. Lời này ta đã muốn nói từ lâu.","Ta không mong ngươi đáp lại ngay; chỉ xin ngươi biết lòng ta.","Mỗi lần nghe tiếng bước chân ngươi, ta lại chẳng giữ nổi bình tâm.","Nếu ngươi nguyện ý, ta muốn cùng ngươi đi hết tiên lộ này."],"oath":["Trời đất chứng giám, ta nguyện kết nghĩa cùng {hero}, hoạn nạn không rời.","Từ nay huynh gặp nguy, đệ lấy kiếm mình chắn trước.","Một chén rượu này kết tình huynh đệ; sống chết, đệ cùng huynh gánh.","Dưới ánh trăng Thanh Vân Sơn, đệ thề không phụ nghĩa kết giao hôm nay."]},"sl":{"rel":{"friend":[["{hero}, cậu cũng bị kẹt trong Cổng này à? Đi chung đi, tôi không thích đánh quái một mình.","Tôi là {npc}. Nếu cậu cần người canh lưng ở {place}, cứ gọi tôi.","Đừng nhìn cấp bậc của tôi rồi lo. Tôi chạy nhanh hơn lũ quái đó.","Cậu vừa cứu tôi một mạng. Ra khỏi Cổng, tôi mời cậu ăn."],["{hero}, tớ đã giữ phần thuốc hồi phục cho cậu. Biết ngay cậu sẽ lại quên mà.","Ở Hiệp Hội ai cũng dè chừng cậu, nhưng tớ biết cậu vẫn là người đã chia nửa ổ bánh với tớ.","Lần sau vào Cổng, nhớ đợi tớ. Cùng đánh thì đỡ buồn hơn.","Tớ nhận ra tiếng bước chân của cậu giữa cả đội hình đấy. Nghe là biết viện binh tới rồi."],["{hero}, Cổng đang sập! Đưa tay đây, tớ không bỏ cậu lại.","Nếu Hiệp Hội muốn đổ lỗi cho cậu, tớ sẽ đứng ra làm chứng.","Đừng một mình gánh hết lũ quái. Tớ vẫn còn đứng đây.","Tớ sợ chứ. Nhưng bỏ cậu giữa Đảo Sương Mù còn đáng sợ hơn."],["Ra khỏi Cổng rồi, {hero}. Lần này đến lượt tớ chọn quán ăn.","Dù cậu có cả binh đoàn bóng tối, chỗ bên cạnh cậu vẫn phải để dành cho tớ.","Từ Ga ngầm Trung Tâm đến tận Đảo Sương Mù, chúng ta đi được xa thật.","Cậu không cần quay đầu kiểm tra nữa. Tớ luôn theo kịp."]],"sworn":[["{hero}, cậu dám giao lưng cho tôi trong một Cổng chưa từng thăm dò sao?","Tôi là {npc}. Nếu sống sót qua đêm nay, chúng ta uống với nhau một chén.","Một mình cậu chặn con boss ấy à? Để tôi góp một tay.","Đường ra ở phía bắc. Tôi mở lối, cậu giữ chân lũ quái."],["Từ hôm nay, hoạn nạn của cậu cũng là chuyện của tôi, {hero}.","Cậu đã kéo tôi khỏi cửa tử. Tôi không quên ơn đó đâu.","Dù {faction} quay lưng, tôi vẫn sát cánh với cậu.","Chén rượu ở {place} hôm ấy chưa cạn. Chúng ta còn nợ nhau một trận thắng."],["Máu tôi còn nóng, kiếm tôi chưa gãy. {hero}, cùng xông lên!","Cậu cứ phá lõi Cổng. Tôi sẽ chặn chúng cho đến hơi thở cuối.","Nếu bóng tối nuốt mất cậu, tôi sẽ bước vào đó kéo cậu ra.","Hôm nay chúng ta sống cùng sống, chết cùng chết. Đừng tranh phần nguy hiểm một mình."],["{hero}, từ nay cậu là anh em của tôi. Không cần giấy của Hiệp Hội làm chứng.","Qua bao nhiêu Cổng, lời thề năm ấy vẫn còn nguyên.","Cứ gọi tên tôi khi cần. Dù ở đâu, tôi cũng sẽ đến.","Chúng ta đã về đủ cả hai. Nào, đi uống nốt chén rượu còn thiếu."]],"sibling":[["Anh là {hero} sao? Em là {npc}... Em đã tìm anh từ rất lâu rồi.","Chiếc vòng này mẹ đưa cho em. Bà nói anh cũng có một chiếc giống hệt.","Em tưởng anh đã mất trong Cổng năm ấy. Cho em nhìn anh thêm một lúc được không?","Em chưa quen gọi anh là anh. Nhưng nghe tên anh, em thấy thân thuộc lạ lắm."],["Anh lại bỏ bữa để đi săn Cổng à? Em để phần cơm trong bếp đấy.","Em không cần anh lúc nào cũng mạnh. Về nhà bình an là được.","Hồi nhỏ anh cũng cau mày mỗi khi lo cho em. Giờ em nhớ ra rồi.","Em đã cất ảnh cũ của chúng ta trong túi. Để lần này không lạc nhau nữa."],["Anh, đừng bước vào Cổng đó một mình! Lần trước em đã mất anh đủ lâu rồi.","Nếu Hệ Thống buộc anh phải lựa chọn, hãy nhớ anh vẫn còn gia đình.","Em sẽ không trốn sau lưng anh mãi. Cho em cùng chiến đấu.","Anh nghe thấy em không? Cứ đi theo giọng em, lối ra ở ngay đây!"],["Anh về rồi. Tốt quá... Em đã giữ đèn phòng khách sáng suốt đêm.","Giờ em có thể nói thật lòng: em rất tự hào vì có anh.","Không Cổng nào chia cắt được nhà mình nữa, anh nhỉ?","Mai em đến Bệnh viện Thánh Tâm thăm mẹ. Anh đi cùng em nhé."]],"lover":[["{hero}, cậu bị thương ở tay kìa. Để mình băng lại.","Mình là {npc}. Hình như chúng ta đã gặp nhau ở {place}?","Cậu cứ lao lên như thế, ai đứng phía sau cũng phải lo đấy.","Không biết tại sao, vừa thấy cậu bước vào Cổng, mình đã thấy yên tâm."],["Mình mang thêm một bình thuốc cho cậu. Đừng hỏi sao mình biết cậu sẽ cần.","Ở cạnh cậu, tiếng còi báo động Cổng cũng bớt đáng sợ.","Cậu cười một cái là mình quên sạch điều định nói.","Sau nhiệm vụ này, cậu có muốn cùng mình đi dạo ở {place} không?"],["{hero}, đừng đẩy mình ra để chịu đòn thay. Mình muốn cùng cậu sống sót.","Mình đã tưởng sẽ không còn được nghe cậu gọi tên. Xin đừng làm mình sợ như vậy nữa.","Dù cả bầu trời trên Cổng vỡ ra, mình vẫn chọn nắm tay cậu.","Nếu đây là trận cuối, mình muốn cậu biết: mình yêu cậu."],["Bình minh lên rồi, {hero}. Lần này chúng ta cùng nhìn thấy nó.","Mình không hứa mọi ngày đều bình yên, chỉ hứa sẽ ở bên cậu.","Bàn tay cậu ấm thật. Cho mình nắm thêm một lát nhé?","Khi không còn Cổng nào phải vào, mình muốn cùng cậu tìm một mái nhà."]],"rival":[["{hero}, nghe nói cậu phá kỷ lục của tôi ở Cổng hạng B. Tôi đến xem có thật không.","Tôi là {npc}. Đừng để tôi vượt qua quá dễ, được chứ?","Cùng một con boss, xem ai chạm tới nó trước.","Cậu mạnh đấy. Tiếc là vị trí số một chỉ có một."],["Tôi tập thêm ba giờ mỗi ngày từ lần thua cậu. Đừng mong trận sau dễ dàng.","Thấy cậu tiến bộ làm tôi bực thật. Nhưng nhờ thế tôi cũng không dám chậm lại.","{faction} đặt cược vào tôi. Cậu đừng khiến họ mất tiền nhanh quá.","Hôm nay tôi cứu cậu vì con boss là phần của tôi. Đừng hiểu lầm."],["{hero}, gạt lũ quái sang một bên. Trận đấu của chúng ta kết thúc hôm nay.","Tôi sẽ không nhận chiến thắng nếu cậu còn đang bị thương. Uống thuốc đi.","Cậu vượt qua giới hạn rồi sao? Hay lắm, tôi cũng vừa làm được.","Lõi Cổng sắp nổ. Chúng ta phân thắng bại trước khi nó sập!"],["Cậu thắng, {hero}. Lần này tôi tâm phục khẩu phục.","Hòa à? Vậy giữ mạng cho tốt, tôi còn muốn đấu trận sau.","Tôi thắng rồi. Nhưng nếu không có cậu, tôi đã chẳng mạnh đến thế.","Từ giờ bớt gọi tôi là đối thủ đi. Khi vào Cổng, tôi muốn đứng cùng đội với cậu."]],"enemy":[["{hero}, cuối cùng ta cũng gặp kẻ được Hiệp Hội che chở.","Ngươi không nhớ ta đâu. Nhưng ta nhớ rất rõ đêm Cổng ở {place} mở ra.","Đừng rút kiếm vội. Ta muốn ngươi nghe vì sao ta đến đây.","Ngươi mang thứ sức mạnh đã hủy đời ta. Ta sẽ không để ngươi đi."],["Trốn trong {faction} cũng vô ích. Ta tìm được dấu vết của ngươi rồi.","Mỗi Cổng ngươi bước qua, ta đều chờ ở lối ra.","Ta đã lấy hồ sơ đêm ấy từ Hiệp Hội. Giờ không ai giấu ngươi khỏi ta được nữa.","Cứ chạy đi, {hero}. Ta muốn ngươi hiểu cảm giác bị săn đuổi."],["Binh đoàn bóng tối không cứu được ngươi khỏi mối hận của ta.","Rút vũ khí đi, {hero}. Đêm nay chỉ một người bước ra khỏi Cổng.","Ngươi nói mình vô tội? Vậy hãy nhìn thẳng vào ta mà nhắc lại.","Ta đã đợi trận này quá lâu. Đừng mong vài lời xin lỗi khiến ta dừng tay."],["Ta đã thua. Ngươi có thể kết liễu ta, nhưng đừng chối bỏ những người đã chết.","Ngươi tha cho ta sao? Ta chưa thể tha thứ, nhưng ta sẽ ngừng truy đuổi.","Mối hận đã kết thúc ở đây. Ta không còn lý do giương kiếm với ngươi.","Ta đã báo được thù. Sao khi nhìn ngươi ngã xuống, ta vẫn thấy trống rỗng?"]],"mentor":[["{hero}, con chỉ nhìn vào móng vuốt. Hãy nhìn vai con quái trước khi nó ra đòn.","Ta là {npc}. Nếu muốn sống qua Cổng đầu tiên, con phải học cách lắng nghe.","Cấp bậc trên giấy không chắn được một nhát kiếm. Nhớ lấy.","Đứng dậy. Ta chưa thấy con thử hết sức."],["Khá hơn rồi. Hôm nay con đã biết bảo vệ đồng đội thay vì chỉ lao tới trước.","Đừng lệ thuộc vào Hệ Thống. Khi nó im lặng, con vẫn phải tự quyết.","Ta không dạy con thắng mọi trận, {hero}. Ta dạy con biết khi nào cần rút lui.","Con nhìn thấy điểm yếu của boss trước ta. Có lẽ đã đến lúc ta đổi bài học."],["Lõi Cổng đang biến dạng. Con dẫn mọi người ra ngoài, ta giữ cửa.","Đừng để lời ta trở thành xiềng xích. Hãy chọn điều con tin là đúng.","{hero}, hít thở. Nỗi sợ giúp con tỉnh táo, miễn là con không để nó cầm kiếm thay mình.","Ta không thể bước tiếp cùng con. Trận này, con phải tự mở đường."],["Con đã trở về. Với ta, thế là một chiến thắng lớn hơn mọi danh hiệu.","Hôm nay ta chẳng còn gì để dạy con nữa. Nhưng nếu cần trò chuyện, cứ đến.","Con đã đi xa hơn ta từng tưởng, {hero}. Hãy dùng sức mạnh ấy cho điều con muốn bảo vệ.","Từ giờ, khi bước vào Cổng, hãy tin vào phán đoán của mình."]]},"links":{"sibling":["{a} và {b} là anh em ruột, thất lạc sau sự cố Cổng ở {place}.","{a} là chị của {b}, luôn giấu thuốc hồi phục trong túi áo em.","{a} và {b} cùng lớn lên tại Bệnh viện Thánh Tâm sau một đợt bùng phát Cổng.","{a} nhận ra {b} nhờ chiếc vòng tay mẹ để lại cho hai người."],"ex":["{a} và {b} từng hẹn hò trước khi gia nhập hai bang hội đối địch.","{a} vẫn giữ tấm ảnh chụp cùng {b} trước Ga ngầm Trung Tâm.","{a} và {b} chia tay sau một nhiệm vụ hạng A, nhưng chưa từng nói hết lòng mình.","{a} tránh nhắc tên {b}, dù vẫn âm thầm hỏi tin sau mỗi cuộc đột kích."],"rival":["{a} và {b} tranh nhau vị trí dẫn đầu bảng xếp hạng thợ săn.","{a} luôn chọn nhiệm vụ khó hơn mỗi khi {b} lập kỷ lục mới.","{a} và {b} đã hòa nhau ba trận tỉ thí liên tiếp.","{a} công khai chê chiến thuật của {b}, nhưng luôn chuẩn bị cách phối hợp với người ấy."],"mentor":["{a} là người dạy {b} cách nhận ra bẫy ma lực trong Cổng.","{a} từng cứu {b} khỏi một con boss và nhận người ấy làm học trò.","{a} giao cho {b} thanh kiếm cũ trước nhiệm vụ đầu tiên.","{a} thường bắt {b} giải thích kế hoạch rút lui trước khi cho vào Cổng."],"debt":["{a} nợ {b} một mạng sau trận sập Cổng tại {place}.","{a} được {b} trả viện phí khi điều trị ở Bệnh viện Thánh Tâm.","{a} hứa sẽ giúp {b} một việc để đáp ơn cứu cả đội.","{a} vẫn giữ chiếc áo khoác {b} đưa trong đêm được giải cứu."],"lover":["{a} và {b} yêu nhau sau nhiều năm cùng dẫn đội đột kích.","{a} luôn đợi {b} trước lối ra Cổng, dù nhiệm vụ kéo dài bao lâu.","{a} và {b} trao nhau lời hẹn ước trên bờ biển Đảo Sương Mù.","{a} và {b} giấu chuyện yêu nhau ở Hiệp Hội, nhưng ai cũng nhận ra."],"enemy":["{a} hận {b} vì tin rằng người ấy đã bỏ mặc đội mình trong Cổng.","{a} truy tìm {b} từ ngày hồ sơ sự cố ở {place} bị niêm phong.","{a} xem {b} là nguyên nhân khiến gia đình mình tan nát.","{a} thề sẽ tự tay đánh bại {b} để đòi lại công bằng."]},"gift":{"like":["Cậu nhớ tôi thích thứ này à? Cảm ơn, {hero}.","Món này khó tìm lắm. Cậu đã vào Cổng chỉ để lấy nó sao?","Tôi sẽ giữ nó cẩn thận. Có lẽ còn cẩn thận hơn cả trang bị của mình.","Đúng thứ tôi cần trước nhiệm vụ ngày mai. Cậu tinh ý thật.","Nhìn món quà này, tôi lại nhớ buổi chúng ta gặp nhau ở {place}.","Cảm ơn cậu. Hôm nay mệt mỏi thế nào cũng đáng."],"dislike":["Cảm ơn cậu, {hero}. Nhưng thứ này không hợp với tôi lắm.","Cậu có chắc không đưa nhầm người không?","Tôi nhận tấm lòng của cậu. Còn món quà... để tôi nghĩ xem dùng thế nào.","Thứ này làm tôi nhớ tới một nhiệm vụ không vui. Xin lỗi cậu.","Lần sau đừng tốn tiền vì tôi như vậy nhé.","Tôi biết cậu có ý tốt. Nhưng tôi không thể nhận món này."]},"join":["Tôi đi cùng cậu, {hero}. Cho tôi xem kế hoạch đột kích.","Được. Tôi sẽ chuẩn bị trang bị rồi gặp cậu ở lối vào Cổng.","Cậu cần người canh hậu tuyến à? Cứ giao cho tôi.","Tôi đã báo với {faction}. Đội mình có thể xuất phát ngay.","Lâu rồi tôi mới thấy một nhiệm vụ đáng để nhận. Đi thôi.","Nếu cậu tin tôi đủ sức theo kịp, tôi sẽ không để cậu thất vọng."],"leave":["Rõ rồi, {hero}. Tôi ở lại căn cứ và giữ liên lạc.","Cậu cứ đi. Tôi sẽ chuẩn bị thuốc và trang bị cho lúc mọi người trở về.","Tôi không thích ngồi chờ, nhưng căn cứ cũng cần người bảo vệ.","Có biến thì gọi ngay. Tôi sẽ đến tiếp viện."],"duel":["{hero}, sân đấu đã dọn xong. Hôm nay đừng giữ sức!","Tôi đã đợi trận tái đấu này lâu lắm rồi. Rút vũ khí đi!","Không quái vật, không đồng đội. Chỉ có cậu và tôi—bắt đầu!","Cho tôi xem sức mạnh đã đưa cậu lên đầu bảng xếp hạng!"],"ambush":["{hero}, ngươi nhìn nhầm lối ra rồi. Ta chờ ở đây từ lâu.","Đừng gọi viện binh. Tín hiệu trong Cổng này đã bị ta cắt.","Bóng của ngươi không che được mọi phía đâu, {hero}!","Bước thêm một bước đi. Toàn bộ hành lang này là bẫy của ta!"],"mercy":["Sao ngươi không kết liễu ta, {hero}? Ta đã định giết ngươi.","Ta không xin được tha thứ. Nhưng ta sẽ không đuổi theo ngươi nữa.","Ngươi thắng rồi. Hãy để ta tự mình tìm ra sự thật về đêm đó.","Ta nợ ngươi một mạng. Mối hận này... ta sẽ để nó dừng ở đây."],"confess":["{hero}, mỗi lần Cổng mở, người mình muốn gặp lại đầu tiên luôn là cậu. Mình yêu cậu.","Mình đã thử giấu đi, nhưng chẳng làm được. Mình thích cậu.","Nếu cậu cũng có chút rung động, sau nhiệm vụ này hãy nắm tay mình nhé?","Mình không muốn chỉ là đồng đội của cậu nữa. Cậu có thể cho mình ở bên cậu không?"],"oath":["{hero}, từ hôm nay chúng ta là anh em kết nghĩa. Có phúc cùng hưởng, có nạn cùng gánh!","Trước Cổng này, tôi thề sẽ không bao giờ bỏ cậu lại phía sau.","Dù cả thế giới quay lưng, tôi vẫn là người anh em đứng cạnh cậu.","Lấy thanh kiếm này làm chứng: mạng cậu cũng là mạng tôi!"]}},"traits":[{"key":"noinong","name":"Nóng nảy","desc":"Dễ bùng giận, nhưng cũng dễ nguôi khi được nói thẳng.","lines":{"greet":["{hero}, đến đúng lúc đấy!","Chào bạn. Có chuyện gì thì nói nhanh nào!","Cậu đây rồi! Tôi chờ đến phát cáu."],"chat":["Tôi ghét nhất kiểu nói nửa câu rồi im.","Giận thì cứ giận, để lâu chỉ thêm mệt.","Có người bảo tôi nên đếm đến mười. Tôi đếm đến ba là đủ.","Nếu tôi lớn tiếng, cứ bảo. Đừng âm thầm tránh mặt.","Tôi thích người nói thật, dù nghe chẳng êm tai."],"fight":["Tránh ra, để tôi!","Đừng thử chọc giận tôi!","Đánh cho xong chuyện này!"],"hurt":["Chỉ xước chút thôi... đau thật đấy!","Được, giờ thì tôi nổi giận rồi."],"like":["Đúng món tôi thích! Bạn nhớ thật à?","Ha! Thế này mới gọi là quà chứ!"],"dislike":["Cậu tặng để xem tôi nổi cáu à?","Thôi được, tôi nhận. Nhưng đừng trông chờ nụ cười."],"tease":["{hero}, cậu chậm thế, tôi giận hộ cả đồng hồ rồi.","Bạn cứ nhìn tôi vậy, muốn thi xem ai cáu trước à?"]}},{"key":"diemdam","name":"Điềm đạm","desc":"Giữ lòng yên giữa những chuyện dễ làm người khác rối trí.","lines":{"greet":["Chào {hero}. Hôm nay bạn thấy thế nào?","Cậu đến rồi. Ta cứ thong thả nói chuyện.","Rất vui được gặp bạn. Ngồi lại một lát nhé?"],"chat":["Một lời nói chậm đôi khi đi xa hơn tiếng quát.","Không phải việc gì cũng cần giải quyết ngay.","Tôi thường nghe hết câu chuyện rồi mới nghĩ đến câu trả lời.","Nếu thấy mỏi, bạn có thể dừng lại một chút.","Mọi chuyện rồi sẽ rõ hơn khi lòng mình lắng xuống."],"fight":["Giữ nhịp thở. Tiến lên.","Đừng vội; nhìn cho kỹ.","Tôi sẽ giữ vững vị trí."],"hurt":["Tôi vẫn ổn. Đừng phân tâm.","Vết thương này cần được chăm sóc, chỉ vậy thôi."],"like":["Cảm ơn bạn. Món quà thật hợp lòng tôi.","Bạn đã để tâm. Tôi trân trọng điều đó."],"dislike":["Cảm ơn. Tôi sẽ giữ lấy tấm lòng của bạn.","Món này không hợp tôi lắm, nhưng ý tốt thì có."],"tease":["{hero}, hiếm khi thấy cậu bối rối đến vậy.","Bạn bảo không vội, sao chân đã bước trước lời rồi?"]}},{"key":"haihuoc","name":"Hài hước","desc":"Lấy tiếng cười làm chiếc ô che những ngày xám xịt.","lines":{"greet":["{hero}! Tôi vừa định kể chuyện cười, may mà có khán giả.","Chào cậu! Hôm nay tôi hứa chỉ đùa một nửa thôi.","Bạn đến rồi à? Nụ cười của tôi vừa có lý do để xuất hiện."],"chat":["Tôi từng thử im lặng cả ngày. Kỷ lục: bốn phút.","Một ngày tệ vẫn có thể kể lại thành chuyện vui.","Bạn có biết điều gì chạy nhanh hơn tôi không? Tin đồn.","Tôi không vụng về; đồ vật chỉ hay tự lao vào tay tôi.","Nếu đời đưa cho tôi câu đố, tôi sẽ xin thêm gợi ý."],"fight":["Nào, đừng làm tôi phải đùa lần hai!","Tôi giữ chân chúng; bạn giữ thể diện cho tôi nhé!","Đánh nhanh lên, tôi sắp hết câu pha trò rồi!"],"hurt":["Ái! Câu đùa đó đau thật.","Tôi vẫn cười được... hơi méo một chút."],"like":["Quà này hay đến mức tôi quên cả câu đùa!","Bạn hiểu gu tôi quá. Đáng ngờ đấy!"],"dislike":["À... bất ngờ thật. Theo nghĩa rất rộng.","Tôi sẽ cất món này ở nơi không ai phải nhìn thấy."],"tease":["{hero}, vẻ mặt đó là kế hoạch hay phần mở đầu trò đùa?","Cậu nghiêm nghị thế, cho tôi mượn một chút được không?"]}},{"key":"nhutnhat","name":"Nhút nhát","desc":"Dè dặt trước người lạ, dịu dàng khi đã thấy an toàn.","lines":{"greet":["À, chào {hero}... tôi mừng vì bạn tới.","Chào cậu. Tôi có nói nhỏ quá không?","Bạn đến rồi... tôi đang tập mở lời trước."],"chat":["Tôi viết sẵn điều muốn nói, rồi lại quên mang theo.","Đông người quá thì đầu tôi trống trơn.","Ở cạnh bạn, tôi thấy dễ thở hơn một chút.","Tôi muốn thử điều mới, chỉ cần thêm chút can đảm.","Đôi khi tôi im lặng vì đang chọn lời, không phải vì buồn."],"fight":["T-tôi ở đây!","Đừng đến gần nữa!","Tôi sợ, nhưng tôi sẽ không chạy!"],"hurt":["Á... đừng lo, tôi còn đứng được.","Tôi cần nghỉ một lát... một lát thôi."],"like":["Cho tôi thật sao? C-cảm ơn bạn!","Tôi thích lắm. Xin lỗi, tôi vui đến nghẹn lời."],"dislike":["Cảm ơn... tôi sẽ cố dùng thử.","À, món này... chắc hợp với người khác hơn."],"tease":["{hero}, lần này đến lượt cậu đỏ mặt nhé?","Bạn cứ trêu tôi mãi. Hôm nay tôi ghi điểm trước rồi."]}},{"key":"kieungao","name":"Kiêu ngạo","desc":"Tin mình vượt trội, nhưng không xem nhẹ người xứng đáng.","lines":{"greet":["{hero}, cuối cùng cậu cũng đến.","Chào bạn. Hy vọng hôm nay có chuyện đáng nghe.","Cậu gặp may đấy; tôi đang có thời gian."],"chat":["Tiêu chuẩn cao không phải lỗi của tôi.","Tôi không cần lời khen, dù nghe cũng dễ chịu.","Người giỏi thật sự biết mình còn thiếu gì.","Tôi ghét thua. Nhất là thua chính mình hôm qua.","Nếu bạn muốn góp ý, hãy đưa ra lý lẽ cho sắc."],"fight":["Lùi lại và xem cho rõ!","Đối thủ như thế chưa đủ đâu!","Tôi sẽ kết thúc chuyện này gọn ghẽ."],"hurt":["Một sơ suất. Không có lần sau.","Vết thương này không quyết định kết quả."],"like":["Khá lắm. Bạn có mắt nhìn đấy.","Món quà xứng đáng được tôi giữ bên mình."],"dislike":["Gu của bạn cần được rèn luyện thêm.","Tôi nhận, để bạn còn cơ hội làm tốt hơn."],"tease":["{hero}, cậu vừa cố gây ấn tượng với tôi à?","Bạn theo kịp tôi rồi đấy... gần như vậy."]}},{"key":"trongnghia","name":"Trọng nghĩa","desc":"Quý lời hứa và luôn tìm cách đáp lại điều tử tế.","lines":{"greet":["{hero}, gặp lại bạn là điều đáng mừng.","Chào cậu. Có việc gì cần tôi góp sức không?","Bạn đến rồi! Tôi vẫn nhớ chuyện hôm trước."],"chat":["Giúp người không nên là phép tính lãi lời.","Một lời hứa nhỏ vẫn là lời hứa.","Tôi nhớ ai đã chìa tay lúc mình cần nhất.","Có món nợ trả bằng tiền được; có món phải trả bằng lòng tốt.","Nếu bạn gặp khó, cứ nói thẳng với tôi."],"fight":["Tôi sẽ không bỏ ai lại!","Vì những người đang trông vào ta!","Đứng cùng nhau, ta còn cơ hội!"],"hurt":["Chưa sao đâu, xem người khác trước!","Tôi chịu được. Đừng để ai ngã nữa."],"like":["Bạn nhớ tôi thích món này. Tôi mang ơn.","Cảm ơn. Lần tới, hãy để tôi đáp lại."],"dislike":["Tấm lòng của bạn quý hơn món quà.","Không hợp tôi lắm, nhưng tôi vẫn cảm ơn."],"tease":["{hero}, cậu giúp tôi nhiều quá; để tôi còn cơ hội trả ơn chứ.","Bạn lại định gánh hết à? Chừa tôi một phần với."]}},{"key":"thamlam","name":"Tham lam","desc":"Luôn muốn thêm một phần, dù đang học cách biết đủ.","lines":{"greet":["{hero}! Cậu mang tin vui hay quà vui?","Chào bạn. Hôm nay có cơ hội gì đáng giá không?","Cậu đến đúng lúc tôi vừa có một ý hay."],"chat":["Tôi thích tiếng đầy lên của một chiếc túi.","Có thêm một chút cũng đâu làm hại ai... nhỉ?","Tôi đang tập chia sẻ. Bắt đầu bằng phần nhỏ trước.","Thứ quý nhất thường bị giấu sau câu 'chẳng có gì'.","Tôi không ôm đồm; tôi chỉ sợ bỏ lỡ."],"fight":["Phần thưởng phía trước, tiến lên!","Đừng hòng lấy mất phần của tôi!","Thắng rồi tính phần sau!"],"hurt":["Ái! Vết thương này phải tính thêm công đấy.","Tôi chưa thể ngã; còn nhiều thứ chưa lấy được!"],"like":["Cho tôi thật à? Bạn rộng rãi quá!","Món này được đấy. Tôi cất kỹ ngay."],"dislike":["Không có món nào khác sao? Tôi hỏi thôi.","Cảm ơn... lần sau mình trao đổi trước nhé?"],"tease":["{hero}, cậu cười với tôi thế là định xin phần à?","Bạn giữ bí mật giỏi thật; tôi tìm mãi chẳng ra quà đâu."]}},{"key":"tuhao","name":"Tự hào","desc":"Trân trọng công sức đã bỏ ra và luôn muốn tiến bộ.","lines":{"greet":["{hero}, đến xem thành quả mới của tôi à?","Chào bạn! Hôm nay tôi có chuyện đáng kể.","Cậu đến rồi. Tôi đang chờ người biết thưởng thức."],"chat":["Tôi nhớ từng lần làm sai để biết mình đã đi xa thế nào.","Được khen thì vui, nhưng làm tốt mới khiến tôi ngủ ngon.","Có những việc nhỏ mà tôi vẫn rất tự hào.","Tôi muốn tên mình gắn với điều tử tế.","Bạn có thành quả nào muốn khoe không? Tôi muốn nghe."],"fight":["Xem tôi đã luyện tập vì điều gì!","Tôi sẽ không phụ công sức của mình!","Đây là lúc chứng minh bản thân!"],"hurt":["Tôi chưa muốn câu chuyện kết thúc ở đây.","Đau đấy, nhưng tôi vẫn đứng vững."],"like":["Bạn hiểu tôi đã cố gắng thế nào. Cảm ơn.","Món quà này, tôi sẽ giữ ở chỗ dễ thấy nhất."],"dislike":["Ý tốt của bạn đáng quý, dù món này không hợp.","Tôi thích sự chân thành hơn. Lần sau cứ hỏi nhé."],"tease":["{hero}, cậu nhìn thành quả của tôi lâu thế, muốn xin chữ ký à?","Bạn khen thêm một câu nữa, tôi sẽ giả vờ khiêm tốn."]}},{"key":"daucam","name":"Đa cảm","desc":"Dễ rung động trước những điều nhỏ bé và nhớ chúng rất lâu.","lines":{"greet":["{hero}, gặp bạn hôm nay làm lòng tôi nhẹ đi.","Chào cậu. Giọng cậu nghe vui hơn lần trước.","Bạn đến rồi... thật tốt quá."],"chat":["Có những câu nói thoáng qua mà tôi nhớ nhiều năm.","Một cử chỉ nhỏ cũng đủ cứu cả ngày buồn.","Tôi hay giữ lại những thứ người khác định bỏ đi.","Tôi vui nhanh, buồn cũng nhanh. May là niềm vui thường quay lại.","Khi ai đó lắng nghe, mọi nỗi niềm bớt nặng."],"fight":["Tôi không muốn ai phải đau thêm!","Dừng lại đi, trước khi quá muộn!","Tôi sẽ bảo vệ những điều mình yêu quý!"],"hurt":["Đau thật... nhưng tôi sẽ ổn.","Đừng nhìn tôi như thế, tôi sắp khóc mất."],"like":["Bạn nhớ điều này sao? Tôi cảm động quá.","Món quà đẹp lắm... cho tôi ngắm thêm chút nhé."],"dislike":["Tôi biết bạn có lòng. Chỉ là món này hơi khó nhận.","Cảm ơn... xin lỗi, tôi không giấu được vẻ mặt."],"tease":["{hero}, cậu nói một câu tử tế rồi tính làm tôi khóc à?","Bạn còn giả vờ không quan tâm nữa, tôi sẽ kể hết đấy."]}},{"key":"lanhlung","name":"Lạnh lùng","desc":"Ít bộc lộ cảm xúc, quan tâm bằng hành động hơn lời nói.","lines":{"greet":["{hero}. Cậu đến rồi.","Chào. Có việc thì nói.","Bạn trông vẫn ổn. Tốt."],"chat":["Im lặng không có nghĩa là tôi không nghe.","Nói ít giúp tôi nhớ điều quan trọng.","Tôi đã kiểm tra rồi. Không có gì đáng ngại.","Bạn mệt thì nghỉ. Tôi canh chừng.","Tôi không giỏi an ủi. Nhưng tôi có thể ở lại."],"fight":["Theo tôi.","Đừng mất tập trung.","Kết thúc nhanh."],"hurt":["Chưa nghiêm trọng.","Tôi vẫn chiến đấu được."],"like":["Hợp ý tôi. Cảm ơn.","Bạn nhớ à... tốt."],"dislike":["Không cần thiết.","Tôi sẽ nhận. Đừng mua thêm."],"tease":["{hero}, cậu nói nhiều thế để che chuyện đang lo à?","Bạn muốn tôi cười? Cố thêm chút nữa."]}},{"key":"tomo","name":"Tò mò","desc":"Luôn lần theo câu hỏi mới, kể cả từ chuyện rất nhỏ.","lines":{"greet":["{hero}! Tôi có ba câu hỏi cho cậu đây.","Chào bạn! Hôm nay bạn thấy gì lạ không?","Cậu tới rồi! Kể tôi nghe chuyện mới đi."],"chat":["Sao người ta nhớ mùi hương lâu đến thế nhỉ?","Tôi thử làm khác đi một chút và phát hiện ra bao điều.","Nếu hỏi 'tại sao' thêm lần nữa, liệu bạn có giận không?","Mỗi người giữ một câu chuyện mà người khác chưa biết.","Tôi thích lúc một câu trả lời mở ra hai câu hỏi mới."],"fight":["Xem chiêu đó hoạt động ra sao nào!","Thú vị đấy, nhưng phải chặn lại!","Tôi muốn biết điểm yếu của chúng!"],"hurt":["Á! Vậy là cách đó không hiệu quả.","Đau quá... nhưng tôi vừa hiểu ra một điều."],"like":["Ồ! Bạn tìm được món này ở đâu?","Tôi thích lắm! Cho tôi xem kỹ chút nhé."],"dislike":["Lạ thật. Món này dùng thế nào?","Không đúng gu tôi, nhưng tôi muốn biết vì sao bạn chọn."],"tease":["{hero}, cậu giấu gì sau lưng? Tôi đoán nhé!","Bạn bảo 'không có gì' tức là chắc chắn có chuyện."]}},{"key":"canthan","name":"Cẩn trọng","desc":"Nghĩ trước một bước và luôn chuẩn bị lối lui.","lines":{"greet":["{hero}, cậu đến an toàn chứ?","Chào bạn. Tôi đã chuẩn bị chỗ ngồi rồi.","Cậu đến đúng giờ. Tốt lắm."],"chat":["Tôi thích kiểm tra lần cuối, rồi mới yên tâm.","Một kế hoạch tốt cũng cần chừa chỗ cho bất ngờ.","Bạn cứ thử, nhưng nhớ nghĩ cách dừng lại trước.","Tôi thường mang theo đồ dự phòng. Và đồ dự phòng của đồ dự phòng.","Cẩn thận không phải sợ; đó là biết mình muốn giữ gì."],"fight":["Giữ khoảng cách!","Quan sát trước khi tiến!","Đừng để bị dồn vào góc!"],"hurt":["Tôi sơ ý rồi. Cần băng vết thương.","Lùi một bước. Tôi phải kiểm tra tình trạng."],"like":["Món này hữu ích. Bạn chu đáo thật.","Cảm ơn. Tôi đã nghĩ đến lúc cần nó."],"dislike":["Tôi chưa biết dùng món này vào việc gì.","Cảm ơn, nhưng lần sau mình bàn trước nhé."],"tease":["{hero}, cậu lại quên kiểm tra túi rồi, đúng không?","Bạn bảo đã có kế hoạch. Để tôi đoán: chưa viết ra?"]}},{"key":"lieulinh","name":"Liều lĩnh","desc":"Thích bước vào điều chưa biết, đôi lúc nhanh hơn suy nghĩ.","lines":{"greet":["{hero}, đi làm chuyện thú vị không?","Chào cậu! Tôi đang ngứa chân đây.","Bạn tới rồi! Đúng lúc tôi cần đồng đội."],"chat":["Tôi thích cảm giác tim đập nhanh trước bước đầu tiên.","Tính mãi thì cơ hội chạy mất.","Tôi biết mình liều. Tôi cũng đang học cách quay đầu.","Một lần thử đáng nhớ hơn mười lần ngồi đoán.","Bạn nói 'không thể' là tôi muốn thử ngay."],"fight":["Theo kịp tôi nhé!","Tôi mở đường!","Cứ tiến lên, rồi tính tiếp!"],"hurt":["Ối! Lần này tôi hơi quá tay.","Đau đấy, nhưng vẫn đáng thử... chắc vậy."],"like":["Tuyệt! Món này đúng chất phiêu lưu!","Bạn tặng thật à? Tôi muốn thử ngay!"],"dislike":["Món này an toàn quá nhỉ.","Cảm ơn, nhưng nó không làm tim tôi nhảy lên chút nào."],"tease":["{hero}, cậu suy nghĩ xong chưa? Tôi đã đi được nửa đường rồi.","Bạn cứ bảo tôi đừng liều, rồi lại theo sát nhất."]}},{"key":"trungthanh","name":"Trung thành","desc":"Đã đặt niềm tin thì không rời đi khi gian khó ập đến.","lines":{"greet":["{hero}, tôi vẫn ở đây.","Chào bạn. Hôm nay ta đi cùng nhau chứ?","Cậu đến rồi. Tôi đã chờ."],"chat":["Tin ai đó là lựa chọn tôi không xem nhẹ.","Khi bạn cần, cứ gọi; tôi sẽ trả lời.","Tôi không hứa điều mình không thể giữ.","Có lúc bất đồng, tôi vẫn sẽ nói thật với bạn.","Tôi muốn là người bạn có thể dựa vào."],"fight":["Tôi ở ngay bên cạnh!","Đừng hòng chia cắt chúng ta!","Cậu tiến lên, tôi giữ phía sau!"],"hurt":["Đừng dừng vì tôi. Tôi theo được.","Tôi chưa rời đội đâu."],"like":["Bạn nhớ đến tôi. Tôi sẽ nhớ điều này.","Cảm ơn. Tôi giữ món quà bên mình."],"dislike":["Tôi nhận tấm lòng, dù món này không hợp.","Lần sau bạn không cần cố chọn quà cho tôi đâu."],"tease":["{hero}, cậu quay lại tìm tôi à? Tôi có đi đâu đâu.","Bạn bước nhanh thế làm tôi phải giả vờ đuổi theo."]}},{"key":"maumo","name":"Mưu mô","desc":"Nhìn ra kẽ hở trong lời nói và luôn giữ lại một quân bài.","lines":{"greet":["{hero}, tôi vừa nghĩ đến cậu.","Chào bạn. Cuộc gặp này đúng lúc thật.","Cậu tới rồi. Tôi đoán cậu sẽ chọn giờ này."],"chat":["Một câu hỏi hay thường tiết lộ nhiều hơn câu trả lời.","Tôi thích để người khác nghĩ họ tự tìm ra ý tưởng.","Ai cũng có điều muốn giấu; vấn đề là giấu để làm gì.","Tôi nghe cả những chỗ người ta ngừng nói.","Đôi khi đường vòng ngắn hơn đường thẳng."],"fight":["Dụ chúng lại gần.","Đúng như tôi dự tính.","Giờ thì đổi thế cờ."],"hurt":["Chậc, tôi tính thiếu một bước.","Tôi sẽ nhớ đòn này."],"like":["Bạn chọn khéo đấy. Tôi thích.","Món quà này khiến tôi phải xem lại dự đoán về bạn."],"dislike":["Một nước đi lạ. Bạn định đạt điều gì?","Tôi nhận. Biết đâu sau này lại có ích."],"tease":["{hero}, cậu nhìn tôi như thế là đang nghi ngờ hay ngưỡng mộ?","Bạn vừa định giấu ý nghĩ đó à? Muộn rồi."]}},{"key":"hiendu","name":"Hiền lành","desc":"Dịu dàng với người khác, nhưng biết đứng lên khi cần.","lines":{"greet":["{hero}, gặp cậu thật vui.","Chào bạn. Tôi để dành cho bạn một chỗ đấy.","Cậu đến rồi! Hôm nay có mệt không?"],"chat":["Tôi tin một lời tử tế có thể ở lại rất lâu.","Nếu bạn muốn kể chuyện, tôi sẽ nghe.","Tôi thích những ngày mọi người được nghỉ ngơi.","Giúp ai đó dễ chịu hơn một chút cũng đáng làm.","Hiền không có nghĩa là để người khác chịu thiệt."],"fight":["Xin lỗi, nhưng tôi phải ngăn lại!","Lùi đi, đừng làm ai bị thương nữa!","Tôi sẽ không để bạn bè chịu đau!"],"hurt":["Tôi ổn... bạn có bị sao không?","Đau một chút thôi. Đừng lo quá."],"like":["Bạn tốt với tôi quá. Cảm ơn nhiều nhé.","Món này khiến tôi vui cả ngày đấy."],"dislike":["Cảm ơn bạn đã nghĩ đến tôi.","Món này không hợp lắm, nhưng tôi quý tấm lòng."],"tease":["{hero}, cậu lại nhường phần ngon rồi, đúng không?","Bạn cứ bảo mình ổn. Tôi pha chút gì ấm cho nhé?"]}},{"key":"nghiemtuc","name":"Nghiêm túc","desc":"Đặt trách nhiệm lên đầu và muốn mọi việc được làm đến nơi.","lines":{"greet":["{hero}, đúng giờ. Bắt đầu được rồi.","Chào bạn. Tôi đã chuẩn bị những điều cần nói.","Cậu tới rồi. Ta vào việc nhé?"],"chat":["Làm cho xong khác với làm cho đúng.","Tôi ghi lại sai sót để lần sau không lặp lại.","Nghỉ ngơi cũng nên có giờ rõ ràng.","Nếu đã nhận việc, tôi muốn theo đến cuối.","Tôi không ghét đùa; chỉ cần đúng lúc."],"fight":["Giữ đội hình!","Tập trung vào mục tiêu!","Làm đúng như đã thống nhất!"],"hurt":["Tôi bị thương. Cần điều chỉnh kế hoạch.","Chưa đến mức phải rút lui."],"like":["Món này thiết thực. Cảm ơn bạn.","Bạn đã chọn rất kỹ. Tôi trân trọng."],"dislike":["Tôi không dùng đến món này.","Cảm ơn, nhưng lần sau xin đừng phí công."],"tease":["{hero}, cậu gọi đó là ghi chú à? Tôi đọc như giải đố.","Bạn đến sớm thế. Tôi suýt mất danh hiệu đúng giờ."]}},{"key":"laquan","name":"Lạc quan","desc":"Luôn tìm một vệt sáng để bắt đầu lại.","lines":{"greet":["{hero}! Hôm nay chắc chắn có điều hay!","Chào cậu! Thấy cậu là ngày sáng hơn rồi.","Bạn đến rồi! Nào, kể tôi nghe tin vui đi."],"chat":["Chưa thành công hôm nay thì mai thử cách khác.","Tôi thích khoảnh khắc ai đó nhận ra mình làm được.","Một ngày khó vẫn có vài phút đáng yêu.","Bạn không cần vui ngay. Tôi sẽ ngồi chờ cùng.","Có lúc tôi cũng nản; rồi tôi nhớ mình đã đi được bao xa."],"fight":["Cố lên, ta làm được!","Còn đứng được là còn cơ hội!","Cùng nhau vượt qua nào!"],"hurt":["Ối! Được rồi, tôi vẫn cười được.","Hơi đau, nhưng ngày này chưa kết thúc đâu!"],"like":["Tuyệt quá! Bạn làm tôi vui thật đấy!","Đúng món tôi thích! Hôm nay có thêm tin vui rồi."],"dislike":["Cảm ơn! Ít nhất tôi biết bạn đã nghĩ đến tôi.","Món này chưa hợp, lần sau ta chọn cùng nhau nhé?"],"tease":["{hero}, cậu cau mày thêm là tôi vẽ mặt cười lên đấy.","Bạn bảo không vui mà chân đang nhún nhảy kìa."]}}]};
